	ld_sril xhl, (xwa + 0x0100)             ; e3 e1 00 01 23 — callback ptr
	ld xwa, 0x007f004b				; 40 4b 00 7f 00
	ld xbc, 0x01c0000f				; 41 0f 00 c0 01
	lds32 xde, 1					; ea a9
	call (xhl)					; b3 e8 — register event
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0084)             ; e3 e1 84 00 23 — (xwa+0x0084) init fn
	call (xhl)					; b3 e8 — call init
	call HDAE5000_Wait_Callback_Loop		; 1d 2b b2 28
	lda_24 xwa, 0x2e21e4			; f2 e4 21 2e 30
	calr HDAE5000_Event_Handler			; 1e 17 ff — register handler
	calr HDAE5000_PPI_Read_Register		; 1e 47 03
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0100)             ; e3 e1 00 01 23
	ld xwa, 0x007f004b				; 40 4b 00 7f 00
	ld xbc, 0x01c0000f				; 41 0f 00 c0 01
	lds32 xde, 0					; ea a8
	call (xhl)					; b3 e8 — unregister event
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xix, (xwa + 0x0100)             ; e3 e1 00 01 24 — xix = callback
	ld xwa, 0x007f0049				; 40 49 00 7f 00
	ld xbc, 0x01e0006b				; 41 6b 00 e0 01
	lds32 xde, 0					; ea a8
	call (xix)					; b4 e8
	cp xhl, 0x00000001				; eb cf 01 00 00 00
	jrl nz, .Leh_epilogue				; 7e 58 02
	; Post-call: push event/subcode, invoke dispatch
	ld xwa, 0x01c00007				; 40 07 00 c0 01
	push xwa					; 38
	ld xwa, 0x0000000a				; 40 0a 00 00 00
	push xwa					; 38
	ld xbc, xiz					; ee 89
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0410)             ; e3 e1 10 04 23 — (xwa+0x0410) dispatch
	ld xwa, 0x00000029				; 40 29 00 00 00
	ld xde, 0xffffffff				; 42 ff ff ff ff
	call (xhl)					; b3 e8
	jrl t, .Leh_epilogue				; 78 2c 02
	; XDE == 0x0A: register event 0x4D, write sector
.Leh_xde_0a:
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0100)             ; e3 e1 00 01 23
	ld xwa, 0x007f004d				; 40 4d 00 7f 00
	ld xbc, 0x01c0000f				; 41 0f 00 c0 01
	lds32 xde, 1					; ea a9
	call (xhl)					; b3 e8
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0084)             ; e3 e1 84 00 23 — init fn
	call (xhl)					; b3 e8
	call HDAE5000_Wait_Callback_Loop		; 1d 2b b2 28
	lda_24 xwa, 0x2e21f0			; f2 f0 21 2e 30
	calr HDAE5000_Event_Handler			; 1e 6b fe
	calr HDAE5000_PPI_Write_Sector			; 1e e2 02
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0100)             ; e3 e1 00 01 23
	ld xwa, 0x007f004d				; 40 4d 00 7f 00
	ld xbc, 0x01c0000f				; 41 0f 00 c0 01
	lds32 xde, 0					; ea a8
	call (xhl)					; b3 e8
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xix, (xwa + 0x0100)             ; e3 e1 00 01 24
	ld xwa, 0x007f0049				; 40 49 00 7f 00
	ld xbc, 0x01e0006b				; 41 6b 00 e0 01
	lds32 xde, 0					; ea a8
	call (xix)					; b4 e8
	cp xhl, 0x00000001				; eb cf 01 00 00 00
	jrl nz, .Leh_epilogue				; 7e ac 01
	ld xwa, 0x01c00007				; 40 07 00 c0 01
	push xwa					; 38
	ld xwa, 0x0000000b				; 40 0b 00 00 00
	push xwa					; 38
	ld xbc, xiz					; ee 89
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0410)             ; e3 e1 10 04 23
	ld xwa, 0x00000029				; 40 29 00 00 00
	ld xde, 0xffffffff				; 42 ff ff ff ff
	call (xhl)					; b3 e8
	jrl t, .Leh_epilogue				; 78 80 01
	; XDE == 0x0B: register event 0x4C, read/check disk status
.Leh_xde_0b:
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0100)             ; e3 e1 00 01 23
	ld xwa, 0x007f004c				; 40 4c 00 7f 00
	ld xbc, 0x01c0000f				; 41 0f 00 c0 01
	lds32 xde, 1					; ea a9
	call (xhl)					; b3 e8
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0084)             ; e3 e1 84 00 23
	call (xhl)					; b3 e8
	call HDAE5000_Wait_Callback_Loop		; 1d 2b b2 28
	lda_24 xwa, 0x2e21fc			; f2 fc 21 2e 30
	calr HDAE5000_Event_Handler			; 1e bf fd
	; Check disk status via 0x0e88 table
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e88)             ; e3 e1 88 0e 20 — (xwa+0x0e88)
	ld xix, (xwa + 0x08)				; a8 08 24
	call (xix)					; b4 e8
	cps l, 3					; cf db
	jr z, .Leh_status_2or3			; 66 04
	cps l, 2					; cf da
	jr nz, .Leh_status_other			; 6e 27
.Leh_status_2or3:
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e88)             ; e3 e1 88 0e 20
	ld xix, (xwa + 0x04)				; a8 04 24
	call (xix)					; b4 e8
	cps hl, 0					; db d8
	jr nz, .Leh_status_nonzero			; 6e 0a
	lda_24 xwa, 0x2e2204			; f2 04 22 2e 30
	calr HDAE5000_Event_Handler			; 1e 8d fd
	jr t, .Leh_after_status			; 68 12
.Leh_status_nonzero:
	lda_24 xwa, 0x2e2208			; f2 08 22 2e 30
	calr HDAE5000_Event_Handler			; 1e 83 fd
	jr t, .Leh_after_status			; 68 08
.Leh_status_other:
	lda_24 xwa, 0x2e220e			; f2 0e 22 2e 30
	calr HDAE5000_Event_Handler			; 1e 79 fd
.Leh_after_status:
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0100)             ; e3 e1 00 01 23
	ld xwa, 0x007f004c				; 40 4c 00 7f 00
	ld xbc, 0x01c0000f				; 41 0f 00 c0 01
	lds32 xde, 0					; ea a8
	call (xhl)					; b3 e8
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xix, (xwa + 0x0100)             ; e3 e1 00 01 24
	ld xwa, 0x007f0049				; 40 49 00 7f 00
	ld xbc, 0x01e0006b				; 41 6b 00 e0 01
	lds32 xde, 0					; ea a8
	call (xix)					; b4 e8
	cp xhl, 0x00000001				; eb cf 01 00 00 00
	jrl nz, .Leh_epilogue				; 7e bd 00
	ld xwa, 0x01c00007				; 40 07 00 c0 01
	push xwa					; 38
	ld xwa, 0x00000009				; 40 09 00 00 00
	push xwa					; 38
	ld xbc, xiz					; ee 89
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0410)             ; e3 e1 10 04 23
	ld xwa, 0x00000029				; 40 29 00 00 00
	ld xde, 0xffffffff				; 42 ff ff ff ff
	call (xhl)					; b3 e8
	jrl t, .Leh_epilogue				; 78 91 00
	; XDE == 0x0C: check device, show status messages
.Leh_xde_0c:
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xix, (xwa + 0x0100)             ; e3 e1 00 01 24
	ld xwa, 0x007f0049				; 40 49 00 7f 00
	ld xbc, 0x01e0006b				; 41 6b 00 e0 01
	lds32 xde, 0					; ea a8
	call (xix)					; b4 e8
	cp xhl, 0x00000001				; eb cf 01 00 00 00
	jr nz, .Leh_xde_0c_no_device			; 6e 27
	; Device present: show "connected" message
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0100)             ; e3 e1 00 01 23
	ld xwa, 0x007f0049				; 40 49 00 7f 00
	ld xbc, 0x01e0003b				; 41 3b 00 e0 01
	lds32 xde, 0					; ea a8
	call (xhl)					; b3 e8
	lda_24 xwa, 0x2e2214			; f2 14 22 2e 30
	calr HDAE5000_Event_Handler			; 1e c0 fc
	jr t, .Leh_epilogue				; 68 45
.Leh_xde_0c_no_device:
	; Device not present: show "not connected" message
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0100)             ; e3 e1 00 01 23
	ld xwa, 0x007f0049				; 40 49 00 7f 00
	ld xbc, 0x01e0003b				; 41 3b 00 e0 01
	lds32 xde, 1					; ea a9
	call (xhl)					; b3 e8
	lda_24 xwa, 0x2e2224			; f2 24 22 2e 30
	calr HDAE5000_Event_Handler			; 1e 99 fc
	; Final cleanup: call deregister via vtable
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0104)             ; e3 e1 04 01 23 — (xwa+0x0104) deregister
	ld xwa, 0xffffffff				; 40 ff ff ff ff
	ld xbc, 0x01c00007				; 41 07 00 c0 01
	ld xde, 0x00000009				; 42 09 00 00 00
	call (xhl)					; b3 e8
	; Epilogue: restore regs, call cleanup callback, return
.Leh_epilogue:
	ld xwa, xiz					; ee 88
	ld xbc, (xsp + 0x08)				; af 08 21
	ld xde, (xsp + 0x04)				; af 04 22
	ld32_24 xhl, 0x23a1a2			; e2 a2 a1 23 23
	ld_sril xhl, (xhl + 0x0e0a)             ; e3 ed 0a 0e 23 — xhl = (xhl+0x0e0a)
	ld_sril xix, (xhl + 0x00dc)             ; e3 ed dc 00 24 — xix = (xhl+0x00dc)
	call (xix)					; b4 e8
.Leh_return:
	pop xiz					; 5e
	inc 0, xsp					; ef 60 — deallocate stack frame
	ret						; 0e

; --- PPI/IDE Low-Level I/O ---
HDAE5000_PPI_Init:	; 0x282B98 (13 bytes)
	; Initialize 8255 PPI: control=0x90 (mode set), port A=0xFF (all bits high)
	sti8_24 0x160006, 0x90                 ; ld (0x160006), 0x90 - PPI control: mode 0, all output
	sti8_24 0x160000, 0xff                 ; ld (0x160000), 0xFF - Port A: set all bits
	ret

HDAE5000_PPI_Transfer_Byte:	; 0x282BA5 (130 bytes)
	; Transfer one byte via PPI to/from IDE bus
	; Input: A = byte to transfer. Returns: L = 0x00 on match, 0xFF on mismatch
	; --- Low nibble phase ---
	ld l, a				; save original byte
	and a, 0x0f			; mask low nibble
	set 4, a			; set bit 4 (data strobe)
	sll a, 3			; shift left 3
	st8_24 0x160002, a                    ; ld (0x160002), A — PPI port B
	ld c, a				; save port B value
	srl c, 6			; shift right 6 for port C
	st8_24 0x160004, c                    ; ld (0x160004), C — PPI port C
	res 7, a			; clear bit 7 (handshake low)
	srl a, 6			; shift right 6
	st8_24 0x160004, a                    ; ld (0x160004), A — PPI port C
	ld xwa, 0x000003E8		; timeout counter (1000)
.Lppi_wait_high:
	bitda_24 4, 1441792		; bit 4, (0x160000) — check ACK
	jr z, .Lppi_wait_high		; wait until bit 4 set
	ld8_24 a, 0x160000                    ; ld A, (0x160000) — read port A
	and a, 0x0f			; mask low nibble
	ld e, a				; save low nibble in E
	; --- High nibble phase ---
	ld a, l				; restore original byte
	srl a, 1			; shift right 1
	res 7, a			; clear bit 7
	st8_24 0x160002, a                    ; ld (0x160002), A — PPI port B
	ld c, a				; save port B value
	srl c, 6			; shift right 6 for port C
	st8_24 0x160004, c                    ; ld (0x160004), C — PPI port C
	set 7, a			; set bit 7 (handshake high)
	srl a, 6			; shift right 6
	st8_24 0x160004, a                    ; ld (0x160004), A — PPI port C
	ld xwa, 0x000003E8		; timeout counter (1000)
.Lppi_wait_low:
	bitda_24 4, 1441792		; bit 4, (0x160000) — check ACK
	jr nz, .Lppi_wait_low		; wait until bit 4 clear
	; --- Reassemble and verify ---
	ld c, e				; C = low nibble
	ld8_24 a, 0x160000                    ; ld A, (0x160000) — read port A
	and a, 0x0f			; mask low nibble (high nibble of result)
	sll a, 4			; shift left 4 to high position
	or a, c				; combine with low nibble
	cp a, l				; compare with original byte
	jr nz, .Lppi_fail		; if mismatch, fail
	ldb l, 0x00			; success: L = 0
	ret
.Lppi_fail:
	ldb l, 0xFF			; failure: L = 0xFF
	ret

HDAE5000_PPI_Read_Register:	; 0x282C27 (71 bytes)
	; Read an IDE register value via PPI
	; Reads register pair (low byte at IZ=0, high byte at IZ=1)
	; Returns 16-bit value in (XSP+2), reports event on success
	dec 2, xsp
	pushw iz
	ldw (xsp + 2), 0x0000		; result = 0
	calr HDAE5000_PPI_Init
	lds iz, 0			; IZ = 0 (loop counter)
	cp iz, 0x0100
	jr ge, .Lppi_rd_loop_end
.Lppi_rd_loop:
	.byte 0xc7, 0xf8, 0x89		; ld a, izl (extended register)
	extz wa
	calr HDAE5000_PPI_Transfer_Byte
	ld a, l				; result byte from transfer
	exts wa				; sign-extend to 16-bit
	or (xsp + 2), wa		; OR into result word
	inc 1, iz
	cp iz, 0x0100
	jr lt, .Lppi_rd_loop
.Lppi_rd_loop_end:
	cpw (xsp + 2), 0x0000	; test if result is zero
	jr nz, .Lppi_rd_nonzero
	lda_24 xwa, 0x2e2234                  ; 0x2E2234 - error event string
	calr HDAE5000_Event_Handler
	jr t, .Lppi_rd_done
.Lppi_rd_nonzero:
	lda_24 xwa, 0x2e224a                  ; 0x2E224A - success event string
	calr HDAE5000_Event_Handler
.Lppi_rd_done:
	popw iz
	inc 2, xsp
	ret

HDAE5000_PPI_Write_Sector:	; 0x282C6E (192 bytes)
	; Write a sector of data to HD via PPI
	; Large 124-byte stack frame for sector buffer and parameter blocks
	lda xsp, (xsp - 124)		; allocate stack frame
	lds wa, 0
	call 0x293E88
	cps hl, 0
	jrl nz, .Lpws_error
	lda xwa, (xsp + 72)
	call 0x297573
	; MemFill: clear 32-byte buffer
	pushw 0x0020			; count = 32
	pushw 0x0000			; fill value = 0
	lda xwa, (xsp + 28)
	push xwa			; buffer address
	call HDAE5000_MemFill
	; MemCopy_Block: copy 46 bytes from 0x2264 offset
	pushw 0x002E			; count = 46
	pushw 0x2264			; source offset
	lda xwa, (xsp + 36)
	push xwa			; dest address
	call HDAE5000_MemCopy_Block
	; MemCopy: copy 10 bytes between buffers
	pushw 0x000A			; count = 10
	lda xwa, (xsp + 100)
	push xwa			; source
	lda xwa, (xsp + 56)
	push xwa			; dest
	call HDAE5000_MemCopy
	lda xsp, (xsp + 26)		; pop all args (26 bytes)
	; Transfer byte to PPI
	lda xwa, (xsp + 24)
	calr HDAE5000_Event_Handler
	; Write sector data
	lda xwa, (xsp + 56)
	call 0x298B6C
	; MemFill: clear buffer again
	pushw 0x0020			; count = 32
	pushw 0x0000			; fill value = 0
	lda xwa, (xsp + 28)
	push xwa			; buffer address
	call HDAE5000_MemFill
	; Compare and copy operations
	lda xbc, (xsp + 76)
	lda xwa, (xsp + 20)
	call 0x29B815
	lda xbc, (xsp + 20)
	lda_24 xde, 0x2e22aa                  ; 0x2E22AA
	lda xwa, (xsp + 20)
	call 0x29B840
	lda xbc, (xsp + 20)
	lda xwa, (xsp + 24)
	call 0x29BA20
	; Copy block via PPI
	lda xiy, (xsp + 24)
	ld xix, (xiy + 4)
	push xix
	ld xix, (xiy + 0)
	push xix
	pushw 0x002E			; count = 46
	pushw 0x2270			; offset
	lda xwa, (xsp + 44)
	push xwa
	call HDAE5000_PPI_Block_Copy
	lda xsp, (xsp + 24)		; pop args
	; Transfer results
	lda xwa, (xsp + 24)
	calr HDAE5000_Event_Handler
	lda_24 xwa, 0x2e2286                  ; 0x2E2286
	calr HDAE5000_Event_Handler
	lda_24 xwa, 0x2e2288                  ; 0x2E2288
	calr HDAE5000_Event_Handler
	jr t, .Lpws_done
.Lpws_error:
	lda_24 xwa, 0x2e2298                  ; 0x2E2298
	calr HDAE5000_Event_Handler
.Lpws_done:
	lda xsp, (xsp + 124)		; deallocate stack frame
	ret

HDAE5000_PPI_Read_Sector:	; 0x282D2E (270 bytes)
	; Read a sector of data from HD via PPI
	; Registers PPI device handlers for read operations via workspace dispatch
	; Copy 14 bytes: source table → PPI buffer
	pushw 0x000E			; count = 14
	lda_24 xwa, 0x2e1ce6                  ; 0x2E1CE6
	push xwa			; source
	lda_24 xwa, 0x22aa9c                  ; 0x22AA9C
	push xwa			; dest
	call HDAE5000_MemCopy
	lda xsp, (xsp + 10)		; pop args
	; Register PPI device: first handler pair (0xDE)
	lda_24 xwa, 0x22aa9c                  ; 0x22AA9C - buffer ptr
	ld xde, xwa
	ld32_24 xwa, 0x23a1a2                 ; workspace ptr (0x23A1A2)
	ld_sril xwa, (xwa + 0x0e0a)             ; (XWA + 0x0E0A)
	ld_sril xhl, (xwa + 0x0124)             ; (XWA + 0x0124)
	ld xwa, 0x007F00DE
	ld xbc, 0x01EA000A
	call (xhl)
	; Register second handler (0xDE, different params)
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)
	ld xwa, 0x007F00DE
	ld xbc, 0x01C0000F
	ld xde, 0xFFFFFFFF
	call (xhl)
	; Copy 241 bytes: second table → PPI buffer
	pushw 0x00F1			; count = 241
	lda_24 xwa, 0x2e1cf4                  ; 0x2E1CF4
	push xwa			; source
	lda_24 xwa, 0x22aaaa                  ; 0x22AAAA
	push xwa			; dest
	call HDAE5000_MemCopy
	lda xsp, (xsp + 10)		; pop args
	; Register PPI device: second handler pair (0xD7)
	lda_24 xwa, 0x22aaaa                  ; 0x22AAAA
	ld xde, xwa
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)
	ld xwa, 0x007F00D7
	ld xbc, 0x01EA000A
	call (xhl)
	; Second handler (0xD7, different params)
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)
	ld xwa, 0x007F00D7
	ld xbc, 0x01C0000F
	ld xde, 0xFFFFFFFF
	call (xhl)
	; Register third handler (0xD9)
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)
	ld xwa, 0x007F00D9
	ld xbc, 0x01C0000D
	lds32 xde, 0
	call (xhl)
	; Register fourth handler (0xD8)
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)
	ld xwa, 0x007F00D8
	ld xbc, 0x01C0000D
	lds32 xde, 0
	call (xhl)
	; Clear two 20-byte buffers
	pushw 0x0014			; count = 20
	pushw 0x0000			; fill = 0
	lda_24 xwa, 0x22ab9c                  ; 0x22AB9C
	push xwa
	call HDAE5000_MemFill
	pushw 0x0014			; count = 20
	pushw 0x0000			; fill = 0
	lda_24 xwa, 0x22abb0                  ; 0x22ABB0
	push xwa
	call HDAE5000_MemFill
	lda xsp, (xsp + 16)		; pop all args (16 bytes)
	ret

HDAE5000_PPI_Transfer_Block:	; 0x282E3C (81 bytes)
	; Transfer a block of data via PPI
	; Iterates entries 1..20, copies block via PPI_Block_Copy, validates buffer,
	; then compares with MemCompare_Block. Returns matching index-1 or 0xFFFF.
	dec 0, xsp			; allocate 8 bytes on stack
	pushw iz
	ld (xsp + 6), xwa		; save input parameter
	lds iz, 1			; IZ = 1 (entry counter)
	cp iz, 0x0014
	jr gt, .Lptb_not_found
.Lptb_loop:
	pushw iz
	pushw 0x002E			; block size = 46
	pushw 0x22AE			; source base address
	lda xwa, (xsp + 8)		; pointer to local buffer
	push xwa
	call HDAE5000_PPI_Block_Copy
	lda xwa, (xsp + 0x0C)		; pointer to compare buffer
	push xwa
	call HDAE5000_Display_Buffer_Validate
	pushw hl			; save validation result
	ld xwa, (xsp + 0x16)		; reload input parameter
	push xwa
	lda xwa, (xsp + 0x16)		; pointer to local buffer
	push xwa
	call HDAE5000_MemCompare_Block
	add xsp, 0x00000018		; clean up stack (24 bytes)
	cps hl, 0			; check compare result
	jr nz, .Lptb_found
	ld hl, iz			; return index - 1
	dec 1, hl
	jr t, .Lptb_done
.Lptb_found:
	inc 1, iz
	cp iz, 0x0014
	jr le, .Lptb_loop
.Lptb_not_found:
	ldw hl, 0xFFFF			; return -1 (not found)
.Lptb_done:
	popw iz
	inc 0, xsp			; deallocate 8 bytes
	ret

; --- HD Drive Setup and Configuration ---
HDAE5000_HD_Setup_Drive:	; 0x282E8D (1126 bytes)
	; Configure HD drive parameters; accesses HD config at 0x229D99
	; Checks disk status, identifies drive, formats partition table, registers events
	.byte 0xf3, 0xfd, 0xf4, 0xfe, 0x37	; lda xsp, (xsp + 0xfef4) — alloc 268-byte frame
	push xiz					; 3e
	.byte 0xbf, 0x04, 0x02, 0x00, 0x00	; ld (xsp+0x04), 0x0000 — clear return value
	; Check disk status via 0x0e88 vtable
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e88)             ; e3 e1 88 0e 20
	ld xix, (xwa + 0x08)				; a8 08 24
	call (xix)					; b4 e8
	cps l, 3					; cf db
	jr z, .Lsd_status_ok				; 66 05
	cps l, 2					; cf da
	jrl nz, .Lsd_not_ready			; 7e 49 02
.Lsd_status_ok:
	; Register event 0xD2 via vtable 0x0124
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23 — (xwa+0x0124)
	ld xwa, 0x007f00d2				; 40 d2 00 7f 00
	ld xbc, 0x01c00001				; 41 01 00 c0 01
	ld xde, 0xffffffff				; 42 ff ff ff ff
	call (xhl)					; b3 e8
	calr HDAE5000_PPI_Read_Sector			; 1e 5b fe
	; Get drive info via 0x0e88.0x0090 vtable
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e88)             ; e3 e1 88 0e 20
	ld_sril xhl, (xwa + 0x0090)             ; e3 e1 90 00 23
	call (xhl)					; b3 e8
	ld xiz, xhl					; eb 8e
	ld xwa, xiz					; ee 88
	or xwa, xwa					; e8 e0 — test if null
	jr z, .Lsd_skip_copy				; 66 18
	; Copy drive info to 0x22aa9c buffer
	ld xwa, xiz					; ee 88
	push xwa					; 38
	call 0x29af71					; 1d 71 af 29
	pushw hl                                ; push hl (compact)
	ld xwa, xiz					; ee 88
	push xwa					; 38
	lda_24 xwa, 0x22aa9c			; f2 9c aa 22 30
	push xwa					; 38
	call 0x29ae9f					; 1d 9f ae 29
	lda xsp, (xsp + 0x0e)			; bf 0e 37
.Lsd_skip_copy:
	; Register event 0xDE via vtable, with 0x22aa9c as data
	lda_24 xwa, 0x22aa9c			; f2 9c aa 22 30
	ld xde, xwa					; e8 8a
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23
	ld xwa, 0x007f00de				; 40 de 00 7f 00
	ld xbc, 0x01ea000a				; 41 0a 00 ea 01
	call (xhl)					; b3 e8
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23
	ld xwa, 0x007f00de				; 40 de 00 7f 00
	ld xbc, 0x01c0000f				; 41 0f 00 c0 01
	ld xde, 0xffffffff				; 42 ff ff ff ff
	call (xhl)					; b3 e8
	; Identify drive: call via 0x0e88.0x0094
	lda_24 xwa, 0x2e22b4			; f2 b4 22 2e 30
	ld xde, xwa					; e8 8a
	lda xwa, (xsp + 0x06)			; bf 06 30
	ld xbc, xwa					; e8 89
	ld xwa, xde					; ea 88
	ld32_24 xde, 0x23a1a2			; e2 a2 a1 23 22
	ld_sril xde, (xde + 0x0e88)             ; e3 e9 88 0e 22
	ld_sril xhl, (xde + 0x0094)             ; e3 e9 94 00 23
	call (xhl)					; b3 e8
	ld xiz, xhl					; eb 8e
	; Check identify result
	ld xwa, xiz					; ee 88
	cp xwa, 0x00000000				; e8 cf 00 00 00 00
	jrl lt, .Lsd_post_loop			; 71 ab 00
	; First pass: process partitions
	lda xwa, (xsp + 0x0c)			; bf 0c 30
	calr HDAE5000_PPI_Transfer_Block		; 1e c4 fe
	ld wa, hl					; db 88
	cp wa, 0xffff					; d8 cf ff ff
	jr z, .Lsd_loop_done				; 66 6e
	ld wa, hl					; db 88
	add wa, 0x0100				; d8 c8 00 01
	lda_24 xbc, 0x22aa9c			; f2 9c aa 22 31
	.byte 0xf3, 0x07, 0xe4, 0xe0, 0x00, 0x01	; ld (xbc+wa), 0x01
	pushw 0x0006					; 0b 06 00
	lda xwa, (xsp + 0x10)			; bf 10 30
	push xwa					; 38
	ld wa, hl					; db 88
	muls wa, 0x000c				; d8 09 0c 00
	lda_24 xbc, 0x22aaad			; f2 ad aa 22 31
	exts xwa					; e8 13
	add xwa, xbc					; e9 80
	push xwa					; 38
	call 0x29ae9f					; 1d 9f ae 29
	lda xsp, (xsp + 0x0a)			; bf 0a 37
	jr t, .Lsd_loop_done				; 68 3d
	; Second pass (loop target for retry)
.Lsd_retry:
	lda xwa, (xsp + 0x0c)			; bf 0c 30
	calr HDAE5000_PPI_Transfer_Block		; 1e 85 fe
	ld wa, hl					; db 88
	cp wa, 0xffff					; d8 cf ff ff
	jr z, .Lsd_loop_done				; 66 2f
	ld wa, hl					; db 88
	add wa, 0x0100				; d8 c8 00 01
	lda_24 xbc, 0x22aa9c			; f2 9c aa 22 31
	.byte 0xf3, 0x07, 0xe4, 0xe0, 0x00, 0x01	; ld (xbc+wa), 0x01
	pushw 0x0006					; 0b 06 00
	lda xwa, (xsp + 0x10)			; bf 10 30
	push xwa					; 38
	ld wa, hl					; db 88
	muls wa, 0x000c				; d8 09 0c 00
	lda_24 xbc, 0x22aaad			; f2 ad aa 22 31
	exts xwa					; e8 13
	add xwa, xbc					; e9 80
	push xwa					; 38
	call 0x29ae9f					; 1d 9f ae 29
	lda xsp, (xsp + 0x0a)			; bf 0a 37
.Lsd_loop_done:
	; Get next partition via 0x0e88.0x0098
	lda xwa, (xsp + 0x06)			; bf 06 30
	ld xbc, xwa					; e8 89
	ld xwa, xiz					; ee 88
	ld32_24 xde, 0x23a1a2			; e2 a2 a1 23 22
	ld_sril xde, (xde + 0x0e88)             ; e3 e9 88 0e 22
	ld_sril xix, (xde + 0x0098)             ; e3 e9 98 00 24
	call (xix)					; b4 e8
	cps hl, 0					; db d8
	jr z, .Lsd_retry				; 66 a7
	; Cleanup: call via 0x0e88.0x009c
	ld xwa, xiz					; ee 88
	ld32_24 xbc, 0x23a1a2			; e2 a2 a1 23 21
	ld_sril xbc, (xbc + 0x0e88)             ; e3 e5 88 0e 21
	ld_sril xhl, (xbc + 0x009c)             ; e3 e5 9c 00 23
	call (xhl)					; b3 e8
.Lsd_post_loop:
	; Format partition display table: loop over 20 entries
	lds de, 0					; da a8
	cp de, 0x0014					; da cf 14 00
	jr nc, .Lsd_display_done			; 6f 56
.Lsd_display_loop:
	ld wa, de					; da 88
	mul wa, 0x000c				; d8 08 0c 00
	add wa, 0x000a				; d8 c8 0a 00
	extz xwa					; e8 12
	add xwa, 0x0000000e				; e8 c8 0e 00 00 00
	ld xbc, 0x0022aa9c				; 41 9c aa 22 00
	add xbc, xwa					; e8 81
	.byte 0xb1, 0x00, 0x20			; ld (xbc), 0x20 — space char
	; Check if partition marked active
	ld wa, de					; da 88
	extz xwa					; e8 12
	add xwa, 0x00000114				; e8 c8 14 01 00 00
	ld xbc, 0x0022aa9c				; 41 9c aa 22 00
	add xbc, xwa					; e8 81
	.byte 0x81, 0x3f, 0x01			; cp (xbc), 0x01
	jr nz, .Lsd_display_next			; 6e 1c
	; Active partition: mark with asterisk
	ld wa, de					; da 88
	mul wa, 0x000c				; d8 08 0c 00
	add wa, 0x000a				; d8 c8 0a 00
	extz xwa					; e8 12
	add xwa, 0x0000000e				; e8 c8 0e 00 00 00
	ld xbc, 0x0022aa9c				; 41 9c aa 22 00
	add xbc, xwa					; e8 81
	.byte 0xb1, 0x00, 0x2a			; ld (xbc), 0x2a — asterisk
.Lsd_display_next:
	inc 1, de					; da 61
	cp de, 0x0014					; da cf 14 00
	jr c, .Lsd_display_loop			; 67 aa
.Lsd_display_done:
	; Register display events via vtable 0x0124
	lda_24 xwa, 0x22aaaa			; f2 aa aa 22 30
	ld xde, xwa					; e8 8a
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23
	ld xwa, 0x007f00d7				; 40 d7 00 7f 00
	ld xbc, 0x01ea000a				; 41 0a 00 ea 01
	call (xhl)					; b3 e8
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23
	ld xwa, 0x007f00d7				; 40 d7 00 7f 00
	ld xbc, 0x01c0000f				; 41 0f 00 c0 01
	ld xde, 0xffffffff				; 42 ff ff ff ff
	call (xhl)					; b3 e8
	; Register event 0xD9 + 0xD8
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23
	ld xwa, 0x007f00d9				; 40 d9 00 7f 00
	ld xbc, 0x01c0000d				; 41 0d 00 c0 01
	lds32 xde, 0					; ea a8
	call (xhl)					; b3 e8
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23
	ld xwa, 0x007f00d8				; 40 d8 00 7f 00
	ld xbc, 0x01c0000d				; 41 0d 00 c0 01
	lds32 xde, 0					; ea a8
	call (xhl)					; b3 e8
	jr t, .Lsd_epilogue				; 68 0a
.Lsd_not_ready:
	; Disk not ready: call shutdown with error code 2
	lds wa, 2					; d8 aa
	calr HDAE5000_HD_Shutdown			; 1e fc 7b
	.byte 0xbf, 0x04, 0x02, 0xff, 0xff	; ld (xsp+0x04), 0xffff — set error
.Lsd_epilogue:
	ld hl, (xsp + 0x04)				; 9f 04 23
	pop xiz					; 5e
	.byte 0xf3, 0xfd, 0x0c, 0x01, 0x37	; lda xsp, (xsp + 0x010c) — dealloc frame
	ret						; 0e
	; --- Sub-handler 1: event 0x01C00007 dispatch (0x28310D) ---
.Lsd_sub1:
	cp xbc, 0x01c00007				; e9 cf 07 00 c0 01
	jr nz, .Lsd_sub1_done			; 6e 63
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xix, (xwa + 0x0100)             ; e3 e1 00 01 24
	ld xwa, 0x02600024				; 40 24 00 60 02
	ld xbc, 0x01e00029				; 41 29 00 e0 01
	call (xix)					; b4 e8
	cp xhl, 0x0000000a				; eb cf 0a 00 00 00
	jr z, .Lsd_sub1_evt_0a			; 66 34
	cp xhl, 0x0000008a				; eb cf 8a 00 00 00
	jr nz, .Lsd_sub1_done			; 6e 38
	; Event 0x8A: check 0x229d99 config
	cpi8_24 0x229d99, 0x00			; c2 99 9d 22 3f 00
	jr nz, .Lsd_sub1_configured			; 6e 05
	calr HDAE5000_HD_Setup_Drive			; 1e 42 fd — recursive setup
	jr t, .Lsd_sub1_done				; 68 2b
.Lsd_sub1_configured:
	; Already configured: register event 0x024A
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23
	ld xwa, 0x007f024a				; 40 4a 02 7f 00
	ld xbc, 0x01c00001				; 41 01 00 c0 01
	lds32 xde, 0					; ea a8
	call (xhl)					; b3 e8
	jr t, .Lsd_sub1_done				; 68 0c
.Lsd_sub1_evt_0a:
	; Event 0x0A: init filesystem
	pushw 0x0000					; 0b 00 00
	lds wa, 0					; d8 a8
	lds bc, 0					; d9 a8
	lds de, 6					; da ae
	calr HDAE5000_FS_Init				; 1e 5e 3f
.Lsd_sub1_done:
	lds32 xhl, 0					; eb a8
	ret						; 0e
	; --- Sub-handler 2: event handler for 0xD9 (0x28317B) ---
.Lsd_sub2:
	push xiz					; 3e
	ld xiz, xwa					; e8 8e
	ld xwa, xbc					; e9 88
	cp xwa, 0x01c00007				; e8 cf 07 00 c0 01
	jr z, .Lsd_sub2_c00007			; 66 63
	cp xwa, 0x01c0000d				; e8 cf 0d 00 c0 01
	jr z, .Lsd_sub2_c0000d			; 66 23
	cp xwa, 0x01e00085				; e8 cf 85 00 e0 01
	jr z, .Lsd_sub2_e00085			; 66 16
	; Default: call cleanup callback
	ld xwa, xiz					; ee 88
	ld32_24 xhl, 0x23a1a2			; e2 a2 a1 23 23
	ld_sril xhl, (xhl + 0x0e0a)             ; e3 ed 0a 0e 23
	ld_sril xix, (xhl + 0x00dc)             ; e3 ed dc 00 24
	call (xix)					; b4 e8
	jrl t, .Lsd_sub2_done				; 78 87 00
.Lsd_sub2_e00085:
	lds32 xhl, 1					; eb a9
	jrl t, .Lsd_sub2_done				; 78 82 00
.Lsd_sub2_c0000d:
	; Forward event via vtable
	ld xwa, xiz					; ee 88
	ld32_24 xhl, 0x23a1a2			; e2 a2 a1 23 23
	ld_sril xhl, (xhl + 0x0e0a)             ; e3 ed 0a 0e 23
	ld_sril xhl, (xhl + 0x00dc)             ; e3 ed dc 00 23
	call (xhl)					; b3 e8
	lda_24 xwa, 0x2e22b8			; f2 b8 22 2e 30
	ld xbc, xwa					; e8 89
	ld xwa, xiz					; ee 88
	ld xde, xbc					; e9 8a
	ld32_24 xbc, 0x23a1a2			; e2 a2 a1 23 21
	ld_sril xbc, (xbc + 0x0e0a)             ; e3 e5 0a 0e 21
	ld_sril xhl, (xbc + 0x0100)             ; e3 e5 00 01 23
	ld xbc, 0x01c0000f				; 41 0f 00 c0 01
	call (xhl)					; b3 e8
	lds32 xhl, 0					; eb a8
	jr t, .Lsd_sub2_done				; 68 4a
.Lsd_sub2_c00007:
	; Check for events 0x07 or 0x06
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xix, (xwa + 0x0100)             ; e3 e1 00 01 24
	ld xwa, 0x02600024				; 40 24 00 60 02
	ld xbc, 0x01e00029				; 41 29 00 e0 01
	call (xix)					; b4 e8
	cp xhl, 0x00000007				; eb cf 07 00 00 00
	jr z, .Lsd_sub2_deregister			; 66 08
	cp xhl, 0x00000006				; eb cf 06 00 00 00
	jr nz, .Lsd_sub2_skip_dereg			; 6e 1d
.Lsd_sub2_deregister:
	; Deregister event via vtable 0x0104
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0104)             ; e3 e1 04 01 23
	ld xwa, 0x007f0000				; 40 00 00 7f 00
	ld xbc, 0x01c00001				; 41 01 00 c0 01
	lds32 xde, 0					; ea a8
	call (xhl)					; b3 e8
.Lsd_sub2_skip_dereg:
	lds32 xhl, 0					; eb a8
.Lsd_sub2_done:
	pop xiz					; 5e
	ret						; 0e
	; --- Sub-handler 3: event handler for 0xD8 (0x283237) ---
.Lsd_sub3:
	push xiz					; 3e
	ld xiz, xwa					; e8 8e
	ld xwa, xbc					; e9 88
	cp xwa, 0x01c00007				; e8 cf 07 00 c0 01
	jr z, .Lsd_sub3_c00007			; 66 63
	cp xwa, 0x01c0000d				; e8 cf 0d 00 c0 01
	jr z, .Lsd_sub3_c0000d			; 66 23
	cp xwa, 0x01e00085				; e8 cf 85 00 e0 01
	jr z, .Lsd_sub3_e00085			; 66 16
	; Default: call cleanup callback
	ld xwa, xiz					; ee 88
	ld32_24 xhl, 0x23a1a2			; e2 a2 a1 23 23
	ld_sril xhl, (xhl + 0x0e0a)             ; e3 ed 0a 0e 23
	ld_sril xix, (xhl + 0x00dc)             ; e3 ed dc 00 24
	call (xix)					; b4 e8
	jrl t, .Lsd_sub3_done				; 78 87 00
.Lsd_sub3_e00085:
	lds32 xhl, 1					; eb a9
	jrl t, .Lsd_sub3_done				; 78 82 00
.Lsd_sub3_c0000d:
	; Forward event via vtable
	ld xwa, xiz					; ee 88
	ld32_24 xhl, 0x23a1a2			; e2 a2 a1 23 23
	ld_sril xhl, (xhl + 0x0e0a)             ; e3 ed 0a 0e 23
	ld_sril xhl, (xhl + 0x00dc)             ; e3 ed dc 00 23
	call (xhl)					; b3 e8
	lda_24 xwa, 0x2e22be			; f2 be 22 2e 30
	ld xbc, xwa					; e8 89
	ld xwa, xiz					; ee 88
	ld xde, xbc					; e9 8a
	ld32_24 xbc, 0x23a1a2			; e2 a2 a1 23 21
	ld_sril xbc, (xbc + 0x0e0a)             ; e3 e5 0a 0e 21
	ld_sril xhl, (xbc + 0x0100)             ; e3 e5 00 01 23
	ld xbc, 0x01c0000f				; 41 0f 00 c0 01
	call (xhl)					; b3 e8
	lds32 xhl, 0					; eb a8
	jr t, .Lsd_sub3_done				; 68 4a
.Lsd_sub3_c00007:
	; Check for events 0x07 or 0x06
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xix, (xwa + 0x0100)             ; e3 e1 00 01 24
	ld xwa, 0x02600024				; 40 24 00 60 02
	ld xbc, 0x01e00029				; 41 29 00 e0 01
	call (xix)					; b4 e8
	cp xhl, 0x00000007				; eb cf 07 00 00 00
	jr z, .Lsd_sub3_deregister			; 66 08
	cp xhl, 0x00000006				; eb cf 06 00 00 00
	jr nz, .Lsd_sub3_skip_dereg			; 6e 1d
.Lsd_sub3_deregister:
	; Deregister event 0xD2 via vtable 0x0104
	ld32_24 xwa, 0x23a1a2			; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0104)             ; e3 e1 04 01 23
	ld xwa, 0x007f00d2				; 40 d2 00 7f 00
	ld xbc, 0x01c00001				; 41 01 00 c0 01
	lds32 xde, 0					; ea a8
	call (xhl)					; b3 e8
.Lsd_sub3_skip_dereg:
	lds32 xhl, 0					; eb a8
.Lsd_sub3_done:
	pop xiz					; 5e
	ret						; 0e

HDAE5000_HD_Read_Identify:	; 0x2832F3 (1051 bytes)
	; Read HD IDENTIFY data; extracts CHS params from 0x229D99-0x229DAB
	; --- Prologue: allocate 32-byte stack frame ---
	lda	xsp, (xsp-32)

	; --- Format CHS display strings ---
	; Block 1: cylinder type (0x229d99) → display buffer 0x22ada6
	pushw 0x0097
	lda_24 xwa, 0x2e22c4			; f2 c4 22 2e 30
	push xwa				; 38
	lda_24 xwa, 0x22ada6			; f2 a6 ad 22 30
	push xwa				; 38
	call 0x29ae9f				; 1d 9f ae 29 — MemCopy
	ld8_24 xwa, 0x229d99			; c2 99 9d 22 21 — ld a, (0x229d99)
	extz wa					; d8 12
	sla wa, 2				; d8 ec 02
	lda_24 xbc, 0x2e1e3c			; f2 3c 1e 2e 31
	ld_sril3 xwa, 0x07, 0xe4, 0xe0		; e3 07 e4 e0 20 — ld xwa, (xbc+wa)
	push xwa				; 38
	pushw 0x002e
	pushw 0x235c
	lda xwa, (xsp + 0x12)			; bf 12 30
	push xwa				; 38
	call HDAE5000_PPI_Block_Copy		; 1d d8 ab 29
	lda xwa, (xsp + 0x16)			; bf 16 30
	push xwa				; 38
	call 0x29af71				; 1d 71 af 29 — Display_Buffer_Validate
	lda xsp, (xsp + 0x1a)			; bf 1a 37

	; Block 2: heads (0x229d9a) → display buffer 0x22adba
	pushw hl                                ; push hl (compact 16-bit)
	lda xwa, (xsp + 0x02)			; bf 02 30
	push xwa				; 38
	lda_24 xwa, 0x22adba			; f2 ba ad 22 30
	push xwa				; 38
	call 0x29ae9f				; 1d 9f ae 29 — MemCopy
	ld8_24 xwa, 0x229d9a			; c2 9a 9d 22 21 — ld a, (0x229d9a)
	extz wa					; d8 12
	sla wa, 2				; d8 ec 02
	lda_24 xbc, 0x2e1e3c			; f2 3c 1e 2e 31
	ld_sril3 xwa, 0x07, 0xe4, 0xe0		; e3 07 e4 e0 20 — ld xwa, (xbc+wa)
	push xwa				; 38
	pushw 0x002e
	pushw 0x2360
	lda xwa, (xsp + 0x12)			; bf 12 30
	push xwa				; 38
	call HDAE5000_PPI_Block_Copy		; 1d d8 ab 29
	lda xwa, (xsp + 0x16)			; bf 16 30
	push xwa				; 38
	call 0x29af71				; 1d 71 af 29 — Display_Buffer_Validate
	lda xsp, (xsp + 0x1a)			; bf 1a 37

	; Block 3: sectors (0x229daa) → display buffer 0x22adec
	pushw hl                                ; push hl (compact 16-bit)
	lda xwa, (xsp + 0x02)			; bf 02 30
	push xwa				; 38
	lda_24 xwa, 0x22adec			; f2 ec ad 22 30
	push xwa				; 38
	call 0x29ae9f				; 1d 9f ae 29 — MemCopy
	ld8_24 xwa, 0x229daa			; c2 aa 9d 22 21 — ld a, (0x229daa)
	extz wa					; d8 12
	pushw wa                                ; push wa (compact 16-bit)
	pushw 0x002e
	pushw 0x2364
	lda xwa, (xsp + 0x10)			; bf 10 30
	push xwa				; 38
	call HDAE5000_PPI_Block_Copy		; 1d d8 ab 29
	lda xwa, (xsp + 0x14)			; bf 14 30
	push xwa				; 38
	call 0x29af71				; 1d 71 af 29 — Display_Buffer_Validate
	lda xsp, (xsp + 0x18)			; bf 18 37

	; Block 4: cylinder count high (0x229da9) → display buffer 0x22ae1e
	pushw hl                                ; push hl (compact 16-bit)
	lda xwa, (xsp + 0x02)			; bf 02 30
	push xwa				; 38
	lda_24 xwa, 0x22ae1e			; f2 1e ae 22 30
	push xwa				; 38
	call 0x29ae9f				; 1d 9f ae 29 — MemCopy
	ld8_24 xwa, 0x229da9			; c2 a9 9d 22 21 — ld a, (0x229da9)
	extz wa					; d8 12
	pushw wa                                ; push wa (compact 16-bit)
	pushw 0x002e
	pushw 0x236a
	lda xwa, (xsp + 0x10)			; bf 10 30
	push xwa				; 38
	call HDAE5000_PPI_Block_Copy		; 1d d8 ab 29
	lda xwa, (xsp + 0x14)			; bf 14 30
	push xwa				; 38
	call 0x29af71				; 1d 71 af 29 — Display_Buffer_Validate
	lda xsp, (xsp + 0x18)			; bf 18 37

	; Block 5: cylinder count (0x229dab) → display buffer 0x22add1
	pushw hl                                ; push hl (compact 16-bit)
	lda xwa, (xsp + 0x02)			; bf 02 30
	push xwa				; 38
	lda_24 xwa, 0x22add1			; f2 d1 ad 22 30
	push xwa				; 38
	call 0x29ae9f				; 1d 9f ae 29 — MemCopy
	ld8_24 xwa, 0x229dab			; c2 ab 9d 22 21 — ld a, (0x229dab)
	extz wa					; d8 12
	pushw wa                                ; push wa (compact 16-bit)
	pushw 0x002e
	pushw 0x2372
	lda xwa, (xsp + 0x10)			; bf 10 30
	push xwa				; 38
	call HDAE5000_PPI_Block_Copy		; 1d d8 ab 29
	lda xwa, (xsp + 0x14)			; bf 14 30
	push xwa				; 38
	call 0x29af71				; 1d 71 af 29 — Display_Buffer_Validate
	lda xsp, (xsp + 0x18)			; bf 18 37

	; Block 6: total size string → display buffer 0x22ae03
	pushw hl                                ; push hl (compact 16-bit)
	lda xwa, (xsp + 0x02)			; bf 02 30
	push xwa				; 38
	lda_24 xwa, 0x22ae03			; f2 03 ae 22 30
	push xwa				; 38
	call 0x29ae9f				; 1d 9f ae 29 — MemCopy
	lda xsp, (xsp + 0x0a)			; bf 0a 37

	; Compute capacity: divide total sectors by 100
	lda xwa, (xsp + 0x10)			; bf 10 30
	call 0x298b6c				; 1d 6c 8b 29
	ld xwa, (xsp + 0x1c)			; af 1c 20 — load dividend
	ld xbc, 0x00000064			; 41 64 00 00 00 — divisor = 100
	call HDAE5000_Divide_Signed		; 1d c5 b8 29
	push xhl				; 3b — push remainder
	pushw 0x002e
	pushw 0x237a
	lda xwa, (xsp + 0x08)			; bf 08 30
	push xwa				; 38
	call HDAE5000_PPI_Block_Copy		; 1d d8 ab 29
	lda xwa, (xsp + 0x0c)			; bf 0c 30
	push xwa				; 38
	call 0x29af71				; 1d 71 af 29 — Display_Buffer_Validate

	; Block 7: capacity text → display buffer 0x22ae35
	pushw hl                                ; push hl (compact 16-bit)
	lda xwa, (xsp + 0x12)			; bf 12 30
	push xwa				; 38
	lda_24 xwa, 0x22ae35			; f2 35 ae 22 30
	push xwa				; 38
	call 0x29ae9f				; 1d 9f ae 29 — MemCopy
	lda xsp, (xsp + 0x1a)			; bf 1a 37

	; --- Register event handlers ---
	; Register event 0x01EA000A with display buffer
	lda_24 xwa, 0x22ada6			; f2 a6 ad 22 30
	ld xde, xwa				; e8 8a
	ld32_24 xwa, 0x23a1a2		; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20 — ld xwa, (xwa+0x0e0a)
	ld_sril xhl, (xwa + 0x0100)             ; e3 e1 00 01 23 — ld xhl, (xwa+0x0100)
	ld xwa, 0x007f000a			; 40 0a 00 7f 00
	ld xbc, 0x01ea000a			; 41 0a 00 ea 01
	call (xhl)				; b3 e8

	; Register event 0x01C0000F with XDE=0xFFFFFFFF (deregister)
	ld32_24 xwa, 0x23a1a2		; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20 — ld xwa, (xwa+0x0e0a)
	ld_sril xhl, (xwa + 0x0100)             ; e3 e1 00 01 23 — ld xhl, (xwa+0x0100)
	ld xwa, 0x007f000a			; 40 0a 00 7f 00
	ld xbc, 0x01c0000f			; 41 0f 00 c0 01
	ld xde, 0xffffffff			; 42 ff ff ff ff
	call (xhl)				; b3 e8

	; --- Epilogue ---
	lda xsp, (xsp + 0x20)			; bf 20 37
	ret					; 0e

; --- Event handler sub-function ---
.Lri_event_handler:				; 0x283498
	dec 0, xsp				; ef 68 — allocate 4 bytes
	push xiz				; 3e
	ld (xsp + 0x04), xde			; bf 04 62
	ld xiz, xbc				; e9 8e
	ld (xsp + 0x08), xwa			; bf 08 60
	ld xwa, xiz				; ee 88
	cp xwa, 0x01c0000d			; e8 cf 0d 00 c0 01
	jr z, .Lri_evt_000d			; 66 xx
	cp xwa, 0x01e00085			; e8 cf 85 00 e0 01
	jr z, .Lri_evt_0085			; 66 xx

	; Default: forward to vtable handler at +0x0EDC
	ld xwa, (xsp + 0x08)			; af 08 20
	ld xbc, xiz				; ee 89
	ld xde, (xsp + 0x04)			; af 04 22
	ld32_24 xhl, 0x23a1a2		; e2 a2 a1 23 23
	ld_sril xhl, (xhl + 0x0e0a)             ; e3 ed 0a 0e 23 — ld xhl, (xhl+0x0e0a)
	ld_sril xix, (xhl + 0x00dc)             ; e3 ed dc 00 24 — ld xix, (xhl+0x00dc)
	call (xix)				; b4 e8
	jr t, .Lri_evt_done			; 68 xx

.Lri_evt_0085:					; 0x2834D0
	lds32 xhl, 1				; eb a9
	jr t, .Lri_evt_done			; 68 xx

.Lri_evt_000d:					; 0x2834D4
	calr HDAE5000_HD_Read_Identify		; 1e xx xx — recursive self-call
	ld xwa, (xsp + 0x08)			; af 08 20
	ld xbc, xiz				; ee 89
	ld xde, (xsp + 0x04)			; af 04 22
	ld32_24 xhl, 0x23a1a2		; e2 a2 a1 23 23
	ld_sril xhl, (xhl + 0x0e0a)             ; e3 ed 0a 0e 23 — ld xhl, (xhl+0x0e0a)
	ld_sril xhl, (xhl + 0x00dc)             ; e3 ed dc 00 23 — ld xhl, (xhl+0x00dc)
	call (xhl)				; b3 e8
	; Re-register event 0x01C0000F with new handler
	lda_24 xwa, 0x2e2382			; f2 82 23 2e 30
	ld xbc, xwa				; e8 89
	ld xwa, (xsp + 0x08)			; af 08 20
	ld xde, xbc				; e9 8a
	ld32_24 xbc, 0x23a1a2		; e2 a2 a1 23 21
	ld_sril xbc, (xbc + 0x0e0a)             ; e3 e5 0a 0e 21 — ld xbc, (xbc+0x0e0a)
	ld_sril xhl, (xbc + 0x0100)             ; e3 e5 00 01 23 — ld xhl, (xbc+0x0100)
	ld xbc, 0x01c0000f			; 41 0f 00 c0 01
	call (xhl)				; b3 e8
	lds32 xhl, 0				; eb a8

.Lri_evt_done:					; 0x283514
	pop xiz					; 5e
	inc 0, xsp				; ef 60
	ret					; 0e

; --- Jump table dispatcher sub-function ---
.Lri_dispatch:					; 0x283518
	cp xbc, 0x01c00013			; e9 cf 13 00 c0 01
	jrl nz, .Lri_done			; 7e xx xx
	ld xwa, xde				; ea 88
	dec 2, xwa				; e8 6a — subtract 2 (cases start at 2)
	cp xwa, 0x00000000			; e8 cf 00 00 00 00
	jrl c, .Lri_done			; 77 xx xx — unsigned < 0
	cp xwa, 0x00000007			; e8 cf 07 00 00 00
	jrl ugt, .Lri_done			; 7b xx xx — > 7
	add xwa, xwa				; e8 80 — multiply by 2 (word offsets)
	add xwa, 0x002e23ac			; e8 c8 ac 23 2e 00 — add table base
	ld wa, (xwa)				; 90 20 — load 16-bit jump offset
	lda_24 xix, 0x28354b			; f2 4b 35 28 34 — jump base
	.byte 0xf3, 0x07, 0xf0, 0xe0, 0xd8	; jp t, (xix+wa) — F3 indexed jump

	; === Case 2: main setup — read/write, format, init filesystem ===
.Lri_jt_base:					; 0x28354B (jump table base)
	sti8_24 0x22ae3c, 0x00			; f2 3c ae 22 00 00
	lda_24 xwa, 0x22ada6			; f2 a6 ad 22 30
	ld xde, xwa				; e8 8a
	ld32_24 xwa, 0x23a1a2		; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20 — ld xwa, (xwa+0x0e0a)
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23 — ld xhl, (xwa+0x0124)
	ld xwa, 0x007f000a			; 40 0a 00 7f 00
	ld xbc, 0x01ea000a			; 41 0a 00 ea 01
	call (xhl)				; b3 e8
	lds wa, 0				; d8 a8
	lds bc, 0				; d9 a8
	calr HDAE5000_HD_Read_Write		; 1e xx xx

	sti8_24 0x22aa4a, 0x00			; f2 4a aa 22 00 00
	lda_24 xwa, 0x22a2ca			; f2 ca a2 22 30
	ld xde, xwa				; e8 8a
	ld32_24 xwa, 0x23a1a2		; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20 — ld xwa, (xwa+0x0e0a)
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23 — ld xhl, (xwa+0x0124)
	ld xwa, 0x007f00fb			; 40 fb 00 7f 00
	ld xbc, 0x01ea000a			; 41 0a 00 ea 01
	call (xhl)				; b3 e8
	lds wa, 0				; d8 a8
	lds bc, 2				; d9 aa
	calr HDAE5000_FS_Write_FSB		; 1e xx xx

	sti8_24 0x22a2c8, 0x00			; f2 c8 a2 22 00 00
	lda_24 xwa, 0x22a0d0			; f2 d0 a0 22 30
	ld xde, xwa				; e8 8a
	ld32_24 xwa, 0x23a1a2		; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20 — ld xwa, (xwa+0x0e0a)
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23 — ld xhl, (xwa+0x0124)
	ld xwa, 0x007f0025			; 40 25 00 7f 00
	ld xbc, 0x01ea000a			; 41 0a 00 ea 01
	call (xhl)				; b3 e8
	ld xwa, 0x007f0025			; 40 25 00 7f 00
	calr HDAE5000_HD_Format_Params		; 1e xx xx
	calr HDAE5000_FS_Read_FSB		; 1e xx xx
	pushw 0x0000
	lds wa, 0				; d8 a8
	lds bc, 0				; d9 a8
	lds de, 6				; da ae
	calr HDAE5000_FS_Init			; 1e xx xx

	; Copy volume label string
	pushw 0x0021
	lda_24 xwa, 0x2e1de6			; f2 e6 1d 2e 30
	push xwa				; 38
	lda_24 xwa, 0x22abc4			; f2 c4 ab 22 30
	push xwa				; 38
	call 0x29ae9f				; 1d 9f ae 29 — MemCopy
	lda xsp, (xsp + 0x0a)			; bf 0a 37

	; Register event for volume label display
	lda_24 xwa, 0x22abc4			; f2 c4 ab 22 30
	ld xde, xwa				; e8 8a
	ld32_24 xwa, 0x23a1a2		; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20 — ld xwa, (xwa+0x0e0a)
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23 — ld xhl, (xwa+0x0124)
	ld xwa, 0x007f0068			; 40 68 00 7f 00
	ld xbc, 0x01ea000a			; 41 0a 00 ea 01
	call (xhl)				; b3 e8

	; Set initial disk status
	ld xwa, 0x007f0000			; 40 00 00 7f 00
	st32_24 0x23a09a, xwa			; f2 9a a0 23 60
	cpi8_24 0x22ad9a, 0x01			; c2 9a ad 22 3f 01
	jrl nz, .Lri_done			; 7e xx xx
	cpi8_24 0x22ad9b, 0x01			; c2 9b ad 22 3f 01
	jrl nz, .Lri_done			; 7e xx xx
	ld xwa, 0x007f013a			; 40 3a 01 7f 00
	st32_24 0x23a09a, xwa			; f2 9a a0 23 60
	jrl t, .Lri_done			; 78 xx xx

	; === Case 9: check cylinder count, set disk capacity ===
.Lri_case9:					; 0x283649
	ld8_24 xwa, 0x229da9			; c2 a9 9d 22 21 — ld a, (0x229da9)
	cps a, 3				; c9 db
	jr z, .Lri_case9_cyl3			; 66 xx
	cps a, 2				; c9 da
	jr z, .Lri_case9_cyl2			; 66 xx
	cps a, 1				; c9 d9
	jrl nz, .Lri_done			; 7e xx xx
	ld xwa, 0x007f0018			; 40 18 00 7f 00
	st32_24 0x23a09a, xwa			; f2 9a a0 23 60
	jrl t, .Lri_done			; 78 xx xx

.Lri_case9_cyl2:				; 0x283668
	ld xwa, 0x007f008f			; 40 8f 00 7f 00
	st32_24 0x23a09a, xwa			; f2 9a a0 23 60
	jrl t, .Lri_done			; 78 xx xx

.Lri_case9_cyl3:				; 0x283675
	ld xwa, 0x007f013a			; 40 3a 01 7f 00
	st32_24 0x23a09a, xwa			; f2 9a a0 23 60
	jrl t, .Lri_done			; 78 xx xx

	; === Case 8: dispatch event to sub-device ===
.Lri_case8:					; 0x283682
	ld32_24 xwa, 0x23a09a		; e2 9a a0 23 20
	ld32_24 xbc, 0x23a1a2		; e2 a2 a1 23 21
	ld_sril xbc, (xbc + 0x0e0a)             ; e3 e5 0a 0e 21 — ld xbc, (xbc+0x0e0a)
	ld_sril xhl, (xbc + 0x0124)             ; e3 e5 24 01 23 — ld xhl, (xbc+0x0124)
	ld xbc, 0x01c00001			; 41 01 00 c0 01
	lds32 xde, 0				; ea a8
	call (xhl)				; b3 e8

	; Deregister event 0x01C00018
	ld32_24 xwa, 0x23a1a2		; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20 — ld xwa, (xwa+0x0e0a)
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23 — ld xhl, (xwa+0x0124)
	ld xwa, 0xffffffff			; 40 ff ff ff ff
	ld xbc, 0x01c00018			; 41 18 00 c0 01
	lds32 xde, 0				; ea a8
	call (xhl)				; b3 e8

	; Check disk presence flags
	cpi8_24 0x22ad9a, 0x01			; c2 9a ad 22 3f 01
	jr nz, .Lri_done			; 6e xx
	cpi8_24 0x22ad9b, 0x01			; c2 9b ad 22 3f 01
	jr nz, .Lri_done			; 6e xx

	; Clear flag and register event 0x01CA0000
	sti8_24 0x22ad9b, 0x00			; f2 9b ad 22 00 00
	ld32_24 xwa, 0x23a1a2		; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20 — ld xwa, (xwa+0x0e0a)
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23 — ld xhl, (xwa+0x0124)
	ld xwa, 0x007f013a			; 40 3a 01 7f 00
	ld xbc, 0x01ca0000			; 41 00 00 ca 01
	lds32 xde, 0				; ea a8
	call (xhl)				; b3 e8
	jr t, .Lri_done				; 68 xx

	; === Case 6: init flag check, set disk size from table ===
.Lri_case6:					; 0x2836F1
	call HDAE5000_Get_Init_Flag		; 1d 70 f5 28
	ld a, l					; cf 89
	extz wa					; d8 12
	sla wa, 2				; d8 ec 02
	lda_24 xbc, 0x2e2388			; f2 88 23 2e 31
	ld_sril3 xwa, 0x07, 0xe4, 0xe0		; e3 07 e4 e0 20 — ld xwa, (xbc+wa)
	st32_24 0x23a09a, xwa			; f2 9a a0 23 60

	; === Common exit ===
.Lri_done:					; 0x28370B
	lds32 xhl, 0				; eb a8
	ret					; 0e

HDAE5000_HD_Format_Params:	; 0x28370E (702 bytes)
	; Format 24 cylinder/head entries into format buffer at 0x22a0d0
	; Args: XWA = context ptr (stored at XSP+0x18)
	; Uses table at 0x23a08e for base offset

	; --- Prologue ---
	lda	xsp, (xsp-26)
	pushw iz                                ; push iz (compact 1-byte)
	ld (xsp + 0x18), xwa		; save context ptr

	; --- Format 0x01F9 entries into buffer ---
	pushw 0x01f9
	pushw 0x0000
	lda_24 xwa, 0x22a0d0
	push xwa
	call 0x29aec7
	inc 0, xsp			; (NOP — callee cleaned stack)

	; --- Loop: format 24 (0x18) entries ---
	lds iz, 0			; IZ = loop counter
	cp iz, 0x0018
	jr ge, .Lfp_loop_done

.Lfp_format_entry:
	; Format field name
	pushw 0x0015
	lda_24 xwa, 0x2e23bc
	push xwa
	ldw wa, 0x0015
	muls xwa, xiz			; XWA = IZ * 21
	lda_24 xbc, 0x22a0d0
	exts xwa
	add xwa, xbc			; XWA = buffer + IZ*21
	push xwa
	call 0x29ae9f
	; Format entry number
	ld wa, iz
	addda16_24 xwa, 0x23a08e	; WA += base offset
	inc 1, wa
	pushw wa                                ; push wa (compact 1-byte)
	pushw 0x002e
	pushw 0x23d2
	lda xwa, (xsp + 0x12)
	push xwa
	call 0x29abd8
	; Format second field
	pushw 0x0003
	lda xwa, (xsp + 0x18)
	push xwa
	ldw wa, 0x0015
	muls xwa, xiz
	lda_24 xbc, 0x22a0d0
	exts xwa
	add xwa, xbc
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x1e)		; clean stack (30 bytes)

	; Load sector address for this entry
	ld16_24 xwa, 0x23a08e	; WA = base offset
	add wa, iz			; WA = base + IZ
	call 0x28f97e			; XHL = sector address
	; Format sector data
	pushw 0x0010
	push xhl
	ldw wa, 0x0015
	muls xwa, xiz
	lda_24 xbc, 0x22a0d4
	exts xwa
	add xwa, xbc
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x0a)		; clean stack

	inc 1, iz
	cp iz, 0x0018
	jr lt, .Lfp_format_entry

.Lfp_loop_done:
	; --- Epilogue: vtable calls ---
	lda_24 xwa, 0x22a0d0
	ld xbc, xwa
	ld xwa, (xsp + 0x18)		; restore context ptr
	ld xde, xbc
	ld32_24 xbc, 0x23a1a2
	ld_sril xbc, (xbc + 0x0e0a)             ; XBC = (XBC + 0x0e0a)
	ld_sril xhl, (xbc + 0x0124)             ; XHL = (XBC + 0x0124)
	ld xbc, 0x01ea000a
	call (xhl)

	ld xwa, (xsp + 0x18)		; restore context ptr
	ld32_24 xbc, 0x23a1a2
	ld_sril xbc, (xbc + 0x0e0a)
	ld_sril xhl, (xbc + 0x0124)
	ld xbc, 0x01c0000f
	ld xde, 0xffffffff
	call (xhl)

	popw iz                                 ; pop iz (compact 1-byte)
	lda xsp, (xsp + 0x1a)		; deallocate 26-byte frame
	ret

; --- HD Format Event Dispatcher (0x2837F2) ---
; Handles event codes 0x01EA0000-0x01EA0008, 0x01C00007
HDAE5000_HD_Format_Dispatch:	; 0x2837F2
	push xiz
	ld xiz, xde			; save XDE in XIZ

	; Dispatch on event code in XBC
	cp xbc, 0x01ea0000
	jrl z, .Lfd_page_down		; 0x01EA0000 = page down
	cp xbc, 0x01ea0001
	jrl z, .Lfd_page_up		; 0x01EA0001 = page up
	cp xbc, 0x01ea0008
	jrl z, .Lfd_seek		; 0x01EA0008 = seek
	cp xbc, 0x01ea0007
	jrl z, .Lfd_set_format		; 0x01EA0007 = set format params
	cp xbc, 0x01ea0006
	jrl z, .Lfd_set_format		; 0x01EA0006 = same handler
	cp xbc, 0x01c00007
	jrl nz, .Lfd_done		; not 0x01C00007 → exit

	; --- Handle 0x01C00007: UI navigation ---
	ld xde, xiz
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)             ; XWA = (XWA + 0x0e0a)
	ld_sril xix, (xwa + 0x0100)             ; XIX = (XWA + 0x0100)
	ld xwa, 0x02600024
	ld xbc, 0x01e00029
	call (xix)			; call UI handler

	; Dispatch on XHL return value
	cp xhl, 0x00000007
	jr z, .Lfd_nav_case7
	cp xhl, 0x00000006
	jr z, .Lfd_nav_case6
	cp xhl, 0x00000005
	jr z, .Lfd_nav_case5
	cp xhl, 0x00000001
	jr z, .Lfd_nav_case1
	or xhl, xhl
	jrl nz, .Lfd_done		; XHL != 0 → exit

	; Case 0: offset = 0x0000
	sti16_24 0x23a08e, 0x0000
	ld xwa, 0x007f0025
	calr HDAE5000_HD_Format_Params
	jrl t, .Lfd_done

.Lfd_nav_case1:
	; Case 1: offset = 0x0018
	sti16_24 0x23a08e, 0x0018
	ld xwa, 0x007f0025
	calr HDAE5000_HD_Format_Params
	jrl t, .Lfd_done

.Lfd_nav_case5:
	; Case 5: offset = 0x0030
	sti16_24 0x23a08e, 0x0030
	ld xwa, 0x007f0025
	calr HDAE5000_HD_Format_Params
	jrl t, .Lfd_done

.Lfd_nav_case6:
	; Case 6: offset = 0x0048
	sti16_24 0x23a08e, 0x0048
	ld xwa, 0x007f0025
	calr HDAE5000_HD_Format_Params
	jrl t, .Lfd_done

.Lfd_nav_case7:
	; Case 7: offset = 0x0060
	sti16_24 0x23a08e, 0x0060
	ld xwa, 0x007f0025
	calr HDAE5000_HD_Format_Params
	jrl t, .Lfd_done

.Lfd_set_format:
	; Handle 0x01EA0006/0007: set format parameters
	ld16_24 xbc, 0x23a08e	; BC = base offset
	ld wa, iz
	add wa, bc
	st16_24 0x23a092, xwa	; store new position
	lds wa, 0			; WA = 0
	lds bc, 0			; BC = 0
	calr HDAE5000_HD_Read_Write	; call HD read/write

	; Notify UI
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)             ; XHL = vtable method
	ld xwa, 0x007f0018
	ld xbc, 0x01c00001
	lds32 xde, 0
	call (xhl)
	jrl t, .Lfd_done

.Lfd_seek:
	; Handle 0x01EA0008: seek operation
	ld16_24 xwa, 0x23a08e	; WA = base offset
	ld bc, iz
	add bc, wa
	st16_24 0x23a092, xbc	; store seek position
	ld wa, bc
	call 0x28f97e			; XHL = sector address
	ld xde, xhl

	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0250)             ; XHL = (XWA + 0x0250) vtable method
	ld xwa, 0x012a0002
	ld xbc, 0x01e00086
	call (xhl)

	; Send completion notification
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)
	ld xwa, 0x007f0058
	ld xbc, 0x01c00001
	lds32 xde, 0
	call (xhl)
	jr t, .Lfd_done

.Lfd_page_up:
	; Handle 0x01EA0001: page up
	cpdi16_24 0x23a08e, 0x0018
	jr lt, .Lfd_done		; already at minimum
	subdi16_24 0x23a08e, 0x0018	; subtract 24 from offset
	ld xwa, 0x007f0025
	calr HDAE5000_HD_Format_Params
	; Calculate new entry index
	ld xwa, xiz
	add xwa, 0x00000018
	ld xde, xwa

	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)
	ld xwa, 0x007f0025
	ld xbc, 0x01ea0003
	call (xhl)
	jr t, .Lfd_done

.Lfd_page_down:
	; Handle 0x01EA0000: page down
	cpdi16_24 0x23a08e, 0x0060
	jr ge, .Lfd_done		; already at maximum
	adddi16_24 0x23a08e, 0x0018	; add 24 to offset
	ld xwa, 0x007f0025
	calr HDAE5000_HD_Format_Params
	; Calculate new entry index
	ld xwa, xiz
	sub xwa, 0x00000018
	ld xde, xwa

	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)
	ld xwa, 0x007f0025
	ld xbc, 0x01ea0003
	call (xhl)

.Lfd_done:
	lds32 xhl, 0
	pop xiz
	ret

HDAE5000_HD_Seek:	; 0x2839CC (412 bytes)
	; Seek to cylinder/head position on HD
	; Args: XWA = context ptr, BC = cylinder, DE = head, (XSP+0x0a) = flags
	; Calls format function (0x29ae9f) with different params based on IZ flags

	; --- Prologue ---
	dec 4, xsp			; allocate 4 bytes
	pushw iz                                ; push iz (compact 1-byte form)
	ld (xsp + 0x02), xwa		; save context ptr
	ld iz, (xsp + 0x0a)		; IZ = flags

	; --- Check BC == 0xFFFF (invalid cylinder) ---
	cp bc, 0xffff
	jr z, .Lhsk_bc_invalid
	cp de, 0xffff			; check DE == 0xFFFF (invalid head)
	jr nz, .Lhsk_check_bits

.Lhsk_bc_invalid:
	pushw 0x007f
	lda_24 xwa, 0x2e2458
	push xwa
	lda_24 xwa, 0x22b274
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x0a)
	jrl t, .Lhsk_epilogue_vtable

.Lhsk_check_bits:
	pushw 0x007f
	lda_24 xwa, 0x2e23d8
	push xwa
	lda_24 xwa, 0x22b274
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x0a)

	cp iz, 0xffff
	jrl z, .Lhsk_iz_invalid

	; --- Bit 0 ---
	bit 0, iz
	jr nz, .Lhsk_bit1
	pushw 0x000e
	lda_24 xwa, 0x2e24d8
	push xwa
	lda_24 xwa, 0x22b274
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x0a)

.Lhsk_bit1:
	bit 1, iz
	jr nz, .Lhsk_bit2
	pushw 0x000e
	lda_24 xwa, 0x2e24d8
	push xwa
	lda_24 xwa, 0x22b282
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x0a)

.Lhsk_bit2:
	bit 2, iz
	jr nz, .Lhsk_bit3
	pushw 0x000e
	lda_24 xwa, 0x2e24d8
	push xwa
	lda_24 xwa, 0x22b290
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x0a)

.Lhsk_bit3:
	bit 3, iz
	jr nz, .Lhsk_bit4
	pushw 0x000e
	lda_24 xwa, 0x2e24d8
	push xwa
	lda_24 xwa, 0x22b29e
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x0a)

.Lhsk_bit4:
	bit 4, iz
	jr nz, .Lhsk_bit5
	pushw 0x000e
	lda_24 xwa, 0x2e24d8
	push xwa
	lda_24 xwa, 0x22b2ac
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x0a)

.Lhsk_bit5:
	bit 5, iz
	jr nz, .Lhsk_bit6
	pushw 0x000e
	lda_24 xwa, 0x2e24d8
	push xwa
	lda_24 xwa, 0x22b2ba
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x0a)

.Lhsk_bit6:
	bit 6, iz
	jr nz, .Lhsk_bit7
	pushw 0x000e
	lda_24 xwa, 0x2e24d8
	push xwa
	lda_24 xwa, 0x22b2c8
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x0a)

.Lhsk_bit7:
	bit 7, iz
	jr nz, .Lhsk_bit8
	pushw 0x000e
	lda_24 xwa, 0x2e24d8
	push xwa
	lda_24 xwa, 0x22b2d6
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x0a)

.Lhsk_bit8:
	bit 8, iz
	jr nz, .Lhsk_epilogue_vtable
	pushw 0x000e
	lda_24 xwa, 0x2e24d8
	push xwa
	lda_24 xwa, 0x22b2e4
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x0a)
	jr t, .Lhsk_epilogue_vtable

.Lhsk_iz_invalid:
	pushw 0x007f
	lda_24 xwa, 0x2e2458
	push xwa
	lda_24 xwa, 0x22b274
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x0a)

.Lhsk_epilogue_vtable:
	; Load vtable and call two methods
	lda_24 xwa, 0x22b274
	ld xbc, xwa
	ld xwa, (xsp + 0x02)		; restore context ptr
	ld xde, xbc
	ld32_24 xbc, 0x23a1a2
	ld_sril xbc, (xbc + 0x0e0a)             ; XBC = (XBC + 0x0e0a)
	ld_sril xhl, (xbc + 0x0124)             ; XHL = (XBC + 0x0124)
	ld xbc, 0x01ea000a
	call (xhl)

	ld xwa, (xsp + 0x02)		; restore context ptr
	ld32_24 xbc, 0x23a1a2
	ld_sril xbc, (xbc + 0x0e0a)             ; XBC = (XBC + 0x0e0a)
	ld_sril xhl, (xbc + 0x0124)             ; XHL = (XBC + 0x0124)
	ld xbc, 0x01c0000f
	ld xde, 0xffffffff
	call (xhl)

	; --- Epilogue ---
	popw iz                                 ; pop iz (compact 1-byte form)
	inc 4, xsp
	retd 0x0002

HDAE5000_HD_Read_Write:	; 0x283B68 (4737 bytes)
; LHRW: 0x283B68 (4737 bytes)

	lda	xsp, (xsp-26)
	pushw iz                                ; push IZ
	.byte 0xbf, 0x18, 0x43                 ; ld (XSP+0x18),C
	.byte 0xbf, 0x1a, 0x41                 ; ld (XSP+0x1a),A
	.byte 0x8f, 0x18, 0x3f, 0x00           ; cp (XSP+0x18),0x00
	jrl nz, .LHRW_3c5d                     ; [7e e4 00] jrl NZ,0x283c5d
	pushw 0x0020
	pushw 0x0000
	lda_24 xwa, 0x22a038
	push xwa
	call 0x29aec7
	pushw 0x002e
	pushw 0x2500
	pushw 0x0022
	pushw 0xa038
	call 0x29af0b
	.byte 0xd2, 0x92, 0xa0, 0x23, 0x20     ; ld WA,(0x23a092)
	inc	1, wa
	pushw wa                                ; push WA
	pushw 0x002e
	pushw 0x250c
	lda	xwa, (xsp+24)
	push xwa
	call 0x29abd8
	lda	xsp, (xsp+26)
	lda	xwa, (xsp+2)
	push xwa
	pushw 0x0022
	pushw 0xa038
	call 0x29af0b
	pushw 0x002e
	pushw 0x2512
	pushw 0x0022
	pushw 0xa038
	call 0x29af0b
	lda	xsp, (xsp+16)
	pushw 0x0010
	.byte 0xd2, 0x92, 0xa0, 0x23, 0x20     ; ld WA,(0x23a092)
	call 0x28f97e
	push xhl
	pushw 0x0022
	pushw 0xa038
	call 0x29af8f
	pushw 0x002e
	pushw 0x2514
	pushw 0x0022
	pushw 0xa038
	call 0x29af0b
	lda	xsp, (xsp+18)
	ld	a, (xsp+26)
	extz wa                                 ; extz WA
	.byte 0xd8, 0xec, 0x02                 ; sla 0x02,WA
	lda_24 xbc, 0x2e24e8
	.byte 0xe3, 0x07, 0xe4, 0xe0, 0x22     ; ld XDE,(XBC+WA)
	lda_24 xwa, 0x22a038
	ld	xbc, xwa
	ld	xwa, xde
	ld	xde, xbc
	ld	xbc, (0x23a1a2)
	.byte 0xe3, 0xe5, 0x0a, 0x0e, 0x21     ; ld XBC,(XBC+0x0e0a)
	.byte 0xe3, 0xe5, 0x24, 0x01, 0x23     ; ld XHL,(XBC+0x0124)
	ld	xbc, 0x01ea000a
	.byte 0xb3, 0xe8                       ; call T,XHL
	ld	a, (xsp+26)
	extz wa                                 ; extz WA
	.byte 0xd8, 0xec, 0x02                 ; sla 0x02,WA
	lda_24 xbc, 0x2e24e8
	.byte 0xe3, 0x07, 0xe4, 0xe0, 0x20     ; ld XWA,(XBC+WA)
	ld	xbc, (0x23a1a2)
	.byte 0xe3, 0xe5, 0x0a, 0x0e, 0x21     ; ld XBC,(XBC+0x0e0a)
	.byte 0xe3, 0xe5, 0x24, 0x01, 0x23     ; ld XHL,(XBC+0x0124)
	ld	xbc, 0x01c0000f
	ld	xde, 0xffffffff
	.byte 0xb3, 0xe8                       ; call T,XHL
.LHRW_3c5d:
	.byte 0x8f, 0x18, 0x3f, 0x00           ; cp (XSP+0x18),0x00
	jrl nz, .LHRW_3d45                     ; [7e e1 00] jrl NZ,0x283d45
	lds	iz, 0
	cp	iz, 0x0010
	jr ge, .LHRW_3ce5                      ; [69 79] jr GE,0x283ce5
.LHRW_3c6c:
	pushw 0x001c
	lda_24 xwa, 0x2e2516
	push xwa
	.byte 0x30, 0x1e, 0x00                 ; ld WA,0x001e
	muls	xwa, xiz
	lda_24 xbc, 0x22ae40
	exts xwa                                ; exts XWA
	add	xwa, xbc
	push xwa
	call 0x29ae9f
	ld	wa, iz
	inc	1, wa
	pushw wa                                ; push WA
	pushw 0x002e
	pushw 0x2534
	lda	xwa, (xsp+18)
	push xwa
	call 0x29abd8
	pushw 0x0002
	lda	xwa, (xsp+24)
	push xwa
	.byte 0x30, 0x1e, 0x00                 ; ld WA,0x001e
	muls	xwa, xiz
	lda_24 xbc, 0x22ae3e
	exts xwa                                ; exts XWA
	add	xwa, xbc
	push xwa
	call 0x29ae9f
	lda	xsp, (xsp+30)
	ld	bc, iz
	.byte 0xd2, 0x92, 0xa0, 0x23, 0x20     ; ld WA,(0x23a092)
	call 0x28fa1e
	pushw 0x001a
	push xhl
	.byte 0x30, 0x1e, 0x00                 ; ld WA,0x001e
	muls	xwa, xiz
	lda_24 xbc, 0x22ae41
	exts xwa                                ; exts XWA
	add	xwa, xbc
	push xwa
	call 0x29ae9f
	lda	xsp, (xsp+10)
	inc	1, iz
	cp	iz, 0x0010
	jr lt, .LHRW_3c6c                      ; [61 87] jr LT,0x283c6c
.LHRW_3ce5:
	ld	a, (xsp+26)
	extz wa                                 ; extz WA
	.byte 0xd8, 0xec, 0x02                 ; sla 0x02,WA
	lda_24 xbc, 0x2e24f0
	.byte 0xe3, 0x07, 0xe4, 0xe0, 0x22     ; ld XDE,(XBC+WA)
	lda_24 xwa, 0x22ae3e
	ld	xbc, xwa
	ld	xwa, xde
	ld	xde, xbc
	ld	xbc, (0x23a1a2)
	.byte 0xe3, 0xe5, 0x0a, 0x0e, 0x21     ; ld XBC,(XBC+0x0e0a)
	.byte 0xe3, 0xe5, 0x24, 0x01, 0x23     ; ld XHL,(XBC+0x0124)
