	lda xwa, (xsp + 0x2c)
	push xwa
	call HDAE5000_PPI_Block_Copy
	lda xwa, (xsp + 0x30)
	push xwa
	call 0x29af71
	lda xsp, (xsp + 0x1c)
	pushw hl                                ; push hl
	lda xwa, (xsp + 0x1a)
	push xwa
	lda_24 xwa, 0x22b3a8
	push xwa
	call 0x29ae9f
	pushw 0x0010
	pushw 0x0000
	lda xwa, (xsp + 0x26)
	push xwa
	call 0x29aec7
	lda xsp, (xsp + 0x12)
	lda xbc, (xsp + 0x2c)
	lda xwa, (xsp + 0x0c)
	call 0x29b815
	lda xbc, (xsp + 0x0c)
	lda_24 xde, 0x2e2cd4
	lda xwa, (xsp + 0x0c)
	call 0x29b840
	lda xbc, (xsp + 0x0c)
	lda xwa, (xsp + 0x10)
	call 0x29ba20
	lda xiy, (xsp + 0x10)
	ld xix, (xiy + 0x04)
	push xix
	ld xix, (xiy)
	push xix
	.byte 0x0b, 0x2e, 0x00		; push 0x002E
	.byte 0x0b, 0xc4, 0x2c		; push 0x2CC4
	lda xwa, (xsp + 0x24)
	push xwa
	call HDAE5000_PPI_Block_Copy
	lda xwa, (xsp + 0x28)
	push xwa
	call 0x29af71
	pushw hl                                ; push hl
	lda xwa, (xsp + 0x2e)
	push xwa
	lda_24 xwa, 0x22b3cf
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x1e)
	pushw 0x0010
	pushw 0x0000
	lda xwa, (xsp + 0x1c)
	push xwa
	call 0x29aec7
	lda xbc, (xsp + 0x3c)
	lda xwa, (xsp + 0x14)
	call 0x29b815
	lda xbc, (xsp + 0x14)
	lda_24 xde, 0x2e2cd8
	lda xwa, (xsp + 0x14)
	call 0x29b840
	lda xbc, (xsp + 0x14)
	lda xwa, (xsp + 0x18)
	call 0x29ba20
	lda xiy, (xsp + 0x18)
	ld xix, (xiy + 0x04)
	push xix
	ld xix, (xiy)
	push xix
	.byte 0x0b, 0x2e, 0x00		; push 0x002E
	.byte 0x0b, 0xca, 0x2c		; push 0x2CCA
	lda xwa, (xsp + 0x2c)
	push xwa
	call HDAE5000_PPI_Block_Copy
	lda xwa, (xsp + 0x30)
	push xwa
	call 0x29af71
	lda xsp, (xsp + 0x1c)
	pushw hl                                ; push hl
	lda xwa, (xsp + 0x1a)
	push xwa
	lda_24 xwa, 0x22b3f6
	push xwa
	call 0x29ae9f
	pushw 0x0010
	pushw 0x0000
	lda xwa, (xsp + 0x26)
	push xwa
	call 0x29aec7
	lda xsp, (xsp + 0x12)
	lda xwa, (xsp + 0x18)
	calr HDAE5000_Display_Clear
	lda xwa, (xsp + 0x18)
	push xwa
	call 0x29af71
	pushw hl                                ; push hl
	lda xwa, (xsp + 0x1e)
	push xwa
	lda_24 xwa, 0x22b41d
	push xwa
	call 0x29ae9f
	lda xsp, (xsp + 0x0e)
	; Register partition display handler
	lda_24 xwa, 0x22b2f6
	ld xde, xwa
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)             ; ld XHL, (XWA + 0x0124)
	ld xwa, 0x007f022a
	ld xbc, 0x01ea000a
	call (xhl)
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)
	ld xwa, 0x007f022a
	ld xbc, 0x01c0000f
	ld xde, 0xffffffff
	call (xhl)
	lda xsp, (xsp + 0x6c)		; deallocate stack frame
	ret
	;
	; Part 2: Event handler (0x286502)
.LHD_PS__handler:
	cp xbc, 0x01c00007
	jrl nz, .LHD_PS__exit
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xix, (xwa + 0x0100)             ; ld XIX, (XWA + 0x0100)
	ld xwa, 0x02600024
	ld xbc, 0x01e00029
	call (xix)
	; Check return value
	cp xhl, 0x0000000c
	jrl z, .LHD_PS__case_0c
	cp xhl, 0x00000009
	jr z, .LHD_PS__case_09
	cp xhl, 0x0000008c
	jrl nz, .LHD_PS__exit
	; Case 0x8C: update display with error code
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)
	ld xwa, 0x007f02c1
	ld xbc, 0x01c00001
	lds32 xde, 5
	call (xhl)
	lds wa, 0
	call 0x293f3c
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)
	ld xwa, 0x007f0013
	ld xbc, 0x01c00001
	lds32 xde, 0
	call (xhl)
	jr t, .LHD_PS__exit
.LHD_PS__case_09:			; case 0x09: format and validate
	.byte 0x0b, 0x0a, 0x00		; push 0x000A
	pushw 0x0000
	lda_24 xwa, 0x22ad9c
	push xwa
	call 0x29aec7
	inc 0, xsp			; deallocate 8 bytes
	cpi8_24 0x229d99, 0x00
	jr nz, .LHD_PS__exit
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)
	ld xwa, 0x007f021a
	ld xbc, 0x01c00001
	lds32 xde, 0
	call (xhl)
	jr t, .LHD_PS__exit
.LHD_PS__case_0c:			; case 0x0C: recursive re-setup
	calr HDAE5000_HD_Partition_Setup
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)
	ld xwa, 0x007f0227
	ld xbc, 0x01c00001
	lds32 xde, 0
	call (xhl)
.LHD_PS__exit:
	lds32 xhl, 0
	ret

HDAE5000_HD_CHS_Calculate:	; 0x2865DE (1098 bytes)
	; Part 1: CHS digit accumulator — stores digit, checks for 6-digit match
	dec 0, xsp			; alloc 4 bytes
	pushw iz                                ; push iz (compact)
	pushw 0x000a
	lda xbc, (xsp + 0x04)
	push xbc
	pushw wa                                ; push wa (compact)
	call 0x29ac3b
	inc 0, xsp			; dealloc 4 bytes
	ld8_24 xwa, 0x22ad9c		; A = current count
	extz wa
	ld bc, wa
	inc 2, bc			; BC = count + 2
	lda_24 xde, 0x22ad9c		; XDE = buffer base
	ld a, (xsp + 0x02)		; A = digit param
	.byte 0xf3, 0x07, 0xe8, 0xe4, 0x41	; ld (XDE+BC), A
	.byte 0xc2, 0x9c, 0xad, 0x22, 0x61	; inc 1, (0x22ad9c)
	cpi8_24 0x22ad9c, 0x06	; count == 6?
	jr nz, .LCHSC__not_full
	; 6 digits entered — match against patterns
	pushw 0x002e
	pushw 0x1e2c
	lda_24 xwa, 0x22ad9e
	push xwa
	call 0x29af2d			; string compare
	inc 0, xsp
	cps hl, 0
	jr nz, .LCHSC__try2
	lds iz, 2			; match pattern 1 → IZ=2
	jr t, .LCHSC__clear
.LCHSC__try2:
	pushw 0x002e
	pushw 0x1e34
	lda_24 xwa, 0x22ad9e
	push xwa
	call 0x29af2d			; string compare
	inc 0, xsp
	cps hl, 0
	jr nz, .LCHSC__no_match
	lds iz, 3			; match pattern 2 → IZ=3
	jr t, .LCHSC__clear
.LCHSC__no_match:
	lds iz, 1			; no match → IZ=1
.LCHSC__clear:
	pushw 0x000a
	pushw 0x0000
	lda_24 xwa, 0x22ad9c
	push xwa
	call 0x29aec7			; MemFill (clear buffer)
	inc 0, xsp
	jr t, .LCHSC__return
.LCHSC__not_full:
	lds iz, 0			; not full → IZ=0
.LCHSC__return:
	ld hl, iz			; return value in HL
	popw iz                                 ; pop iz (compact)
	inc 0, xsp			; dealloc 4 bytes
	ret
	;
	; Part 2: Event handler (0x286666)
.LCHSC__handler:
	dec 6, xsp			; alloc 24 bytes
	push xiz
	ld xiz, xde			; XIZ = param
	ld (xsp + 0x06), xwa		; save event code
	ld xwa, xbc			; XWA = event code
	cp xwa, 0x01ca0002
	jrl z, .LCHSC__ev_close
	cp xwa, 0x01c00007
	jr z, .LCHSC__ev_key
	cp xwa, 0x01c0000d
	jr z, .LCHSC__ev_0d
	cp xwa, 0x01e00085
	jr z, .LCHSC__ev_85
	; Default: pass through to registered handler
	ld xwa, (xsp + 0x06)
	ld xde, xiz
	ld32_24 xhl, 0x23a1a2
	ld_sril xhl, (xhl + 0x0e0a)             ; XHL = (XHL + 0x0E0A)
	ld_sril xix, (xhl + 0x00dc)             ; XIX = (XHL + 0x00DC)
	call (xix)
	jrl t, .LCHSC__exit
.LCHSC__ev_85:				; Event 0x01E00085
	lds32 xhl, 1
	jrl t, .LCHSC__exit
.LCHSC__ev_0d:				; Event 0x01C0000D
	ld xwa, (xsp + 0x06)
	ld xde, xiz
	ld32_24 xhl, 0x23a1a2
	ld_sril xhl, (xhl + 0x0e0a)
	ld_sril xhl, (xhl + 0x00dc)             ; XHL = (XHL + 0x00DC)
	call (xhl)
	lda_24 xwa, 0x2e2cdc
	ld xbc, xwa
	ld xwa, (xsp + 0x06)
	ld xde, xbc
	ld32_24 xbc, 0x23a1a2
	ld_sril xbc, (xbc + 0x0e0a)             ; XBC = (XBC + 0x0E0A)
	ld_sril xhl, (xbc + 0x0100)             ; XHL = (XBC + 0x0100)
	ld xbc, 0x01c0000f
	call (xhl)
	lds32 xhl, 0
	jrl t, .LCHSC__exit
.LCHSC__ev_key:				; Event 0x01C00007
	.byte 0xbf, 0x04, 0x02, 0x00, 0x00	; ld (XSP+0x04), 0x0000
	ld xde, xiz
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)             ; XWA = (XWA + 0x0E0A)
	ld_sril xix, (xwa + 0x0100)             ; XIX = (XWA + 0x0100)
	ld xwa, 0x02600024
	ld xbc, 0x01e00029
	call (xix)
	ld xwa, xhl
	cp xwa, 0x00000007
	jrl ugt, .LCHSC__post_switch		; > 7 → skip
	add xwa, xwa				; XWA * 2
	add xwa, 0x002e2ce2			; jump table base
	ld wa, (xwa)				; WA = offset
	lda_24 xix, 0x28672d			; dispatch base
	.byte 0xf3, 0x07, 0xf0, 0xe0, 0xd8	; jp (XIX + WA)
	; Case 0: bit test → call with 0/1
	bit 0x07, iz
	jr z, .LCHSC__c0_even
	lds wa, 0
	jr t, .LCHSC__c0_call
.LCHSC__c0_even:
	lds wa, 1
.LCHSC__c0_call:
	calr HDAE5000_HD_CHS_Calculate		; recursive
	ld (xsp + 0x04), hl
	jr t, .LCHSC__post_switch
	; Case 1: bit test → call with 2/3
	bit 0x07, iz
	jr z, .LCHSC__c1_even
	lds wa, 2
	jr t, .LCHSC__c1_call
.LCHSC__c1_even:
	lds wa, 3
.LCHSC__c1_call:
	calr HDAE5000_HD_CHS_Calculate
	ld (xsp + 0x04), hl
	jr t, .LCHSC__post_switch
	; Case 2: bit test → call with 4/5
	bit 0x07, iz
	jr z, .LCHSC__c2_even
	lds wa, 4
	jr t, .LCHSC__c2_call
.LCHSC__c2_even:
	lds wa, 5
.LCHSC__c2_call:
	calr HDAE5000_HD_CHS_Calculate
	ld (xsp + 0x04), hl
	jr t, .LCHSC__post_switch
	; Case 3: bit test → call with 6/7
	bit 0x07, iz
	jr z, .LCHSC__c3_even
	lds wa, 6
	jr t, .LCHSC__c3_call
.LCHSC__c3_even:
	lds wa, 7
.LCHSC__c3_call:
	calr HDAE5000_HD_CHS_Calculate
	ld (xsp + 0x04), hl
	jr t, .LCHSC__post_switch
	; Case 4: bit test → call with 8/9 (ldw for values > 7)
	bit 0x07, iz
	jr z, .LCHSC__c4_even
	ldw wa, 0x0008
	jr t, .LCHSC__c4_call
.LCHSC__c4_even:
	ldw wa, 0x0009
.LCHSC__c4_call:
	calr HDAE5000_HD_CHS_Calculate
	ld (xsp + 0x04), hl
	jr t, .LCHSC__post_switch
	; Case 6/7: clear buffer + display setup
	pushw 0x000a
	pushw 0x0000
	lda_24 xwa, 0x22ad9c
	push xwa
	call 0x29aec7			; MemFill
	inc 0, xsp
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)             ; XHL = (XWA + 0x0104)
	ld xwa, 0x007f0013
	ld xbc, 0x01c00001
	lds32 xde, 0
	call (xhl)
	; Post-switch: dispatch on result
.LCHSC__post_switch:
	ld wa, (xsp + 0x04)
	cps wa, 3
	jrl z, .LCHSC__res3
	cps wa, 2
	jr z, .LCHSC__res2
	cps wa, 1
	jrl nz, .LCHSC__done
	; Result 1: setup with 0x007f02cb + two dialog boxes
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0100)             ; XHL = (XWA + 0x0100)
	ld xwa, 0x007f02cb
	ld xbc, 0x01c00001
	lds32 xde, 3
	call (xhl)
	ld xwa, 0x01ca0002
	push xwa
	ld xwa, 0x007f021a
	push xwa
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0418)             ; XHL = (XWA + 0x0418)
	ld xwa, 0x0000014d
	ld xbc, 0x007f02cd
	ld xde, 0xffffffff
	call (xhl)
	ld xwa, 0x01ca0002
	push xwa
	ld xwa, 0x007f021a
	push xwa
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0410)             ; XHL = (XWA + 0x0410)
	ld xwa, 0x0000014d
	ld xbc, 0x007f02cd
	ld xde, 0xffffffff
	call (xhl)
	jrl t, .LCHSC__done
.LCHSC__res2:				; Result 2: display setup + validate + FS init
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0100)
	ld xwa, 0x007f0223
	ld xbc, 0x01c00001
	lds32 xde, 0
	call (xhl)
	calr HDAE5000_Wait_Callback_Loop
	lds wa, 1
	call 0x28f90c
	cps hl, 0
	jr nz, .LCHSC__res2_err
	; Success: display + FS read
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)
	ld xwa, 0x007f0013
	ld xbc, 0x01c00001
	lds32 xde, 0
	call (xhl)
	ld xwa, 0x007f0025
	calr HDAE5000_HD_Format_Params
	lds wa, 0
	lds bc, 0
	calr HDAE5000_HD_Read_Write
	calr HDAE5000_FS_Read_FSB
	lds wa, 0
	lds bc, 2
	calr HDAE5000_FS_Write_FSB
	jrl t, .LCHSC__done
.LCHSC__res2_err:			; Error: display error + two dialog boxes
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)
	ld xwa, 0x007f02c4
	ld xbc, 0x01c00001
	lds32 xde, 3
	call (xhl)
	ld xwa, 0x01ca0002
	push xwa
	ld xwa, 0x007f021a
	push xwa
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0418)
	ld xwa, 0x0000014d
	ld xbc, 0x007f02c6
	ld xde, 0xffffffff
	call (xhl)
	ld xwa, 0x01ca0002
	push xwa
	ld xwa, 0x007f021a
	push xwa
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0410)
	ld xwa, 0x0000014d
	ld xbc, 0x007f02c6
	ld xde, 0xffffffff
	call (xhl)
	jrl t, .LCHSC__done
.LCHSC__res3:				; Result 3: set flags + validate + check match
	sti8_24 0x229da9, 0x01
	sti8_24 0x229daa, 0x01
	sti8_24 0x229dab, 0x01
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0100)
	ld xwa, 0x007f0294
	ld xbc, 0x01c00001
	lds32 xde, 0
	call (xhl)
	calr HDAE5000_Wait_Callback_Loop
	lds wa, 0
	call 0x293f3c
	cp hl, 0xffff
	jr z, .LCHSC__res3_nomatch
	; Match found
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)
	ld xwa, 0x007f0013
	ld xbc, 0x01c00001
	lds32 xde, 0
	call (xhl)
	jrl t, .LCHSC__done
.LCHSC__res3_nomatch:			; No match — setup error display + dialog boxes
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)
	ld xwa, 0x007f0297
	ld xbc, 0x01c00001
	lds32 xde, 3
	call (xhl)
	ld xwa, 0x007f0298
	ld xbc, 0x007f021a
	calr HDAE5000_UI_Main_Handler
	ld xwa, 0x01ca0002
	push xwa
	ld xwa, 0x007f021a
	push xwa
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0418)
	ld xwa, 0x0000014d
	ld xbc, 0x007f0299
	ld xde, 0xffffffff
	call (xhl)
	ld xwa, 0x01ca0002
	push xwa
	ld xwa, 0x007f021a
	push xwa
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0410)
	ld xwa, 0x0000014d
	ld xbc, 0x007f0299
	ld xde, 0xffffffff
	call (xhl)
.LCHSC__done:				; Common exit
	lds32 xhl, 0
	jr t, .LCHSC__exit
.LCHSC__ev_close:			; Event 0x01CA0002: close display
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)
	ld xwa, 0x007f021a
	ld xbc, 0x01c00001
	lds32 xde, 0
	call (xhl)
	lds32 xhl, 0
.LCHSC__exit:
	pop xiz
	inc 6, xsp			; dealloc 24 bytes
	ret

HDAE5000_HD_Sector_Read:	; 0x286A28 (1064 bytes)
	; Read sectors from HD; accesses 0x229DAC
	; Part 1: CHS input state machine with jump table dispatch
	pushw iz                                ; push iz (compact)
	ld hl, (xsp + 0x06)		; HL = param from stack
	ld de, wa			; DE = input digit
	ld16_24 xwa, 0x22aa5c	; load current state
	cps wa, 5			; state >= 6? (unsigned)
	jrl ugt, .LHD_SR__apply	; yes → apply values
	add wa, wa			; state * 2
	lda_24 xix, 0x2e2cf2		; jump table base
	.byte 0xd3, 0x07, 0xf0, 0xe0, 0x20	; ld WA, (XIX + WA)
	lda_24 xix, 0x286a4e		; dispatch base
	.byte 0xf3, 0x07, 0xf0, 0xe0, 0xd8	; jp (XIX + WA)
	; Case 0 (offset 0x0000): jump to FS_Init directly
	jrl t, .LHD_SR__cleanup
	; Case 1 (offset 0x0003): cylinder digit * 100
	ld wa, hl
	muls wa, 0x0064			; WA = digit * 100
	add de, wa			; DE += WA
	cp de, 0x0064			; DE >= 100?
	jr lt, .LHD_SR__c1_lo
	ldw de, 0x0064			; clamp to 100
	jr t, .LHD_SR__apply
.LHD_SR__c1_lo:
	cps de, 0			; DE > 0?
	jr gt, .LHD_SR__apply
	lds de, 0			; clamp to 0
	jr t, .LHD_SR__apply
	; Case 2 (offset 0x001E): cylinder digit * 10
	ld wa, hl
	muls wa, 0x000a			; WA = digit * 10
	add de, wa
	cp de, 0x0078			; DE >= 120?
	jr lt, .LHD_SR__c2_lo
	ldw de, 0x0078			; clamp to 120
	jr t, .LHD_SR__apply
.LHD_SR__c2_lo:
	cps de, 1			; DE > 1?
	jr gt, .LHD_SR__apply
	lds de, 0
	jr t, .LHD_SR__apply
	; Case 3 (offset 0x0039): cylinder unit digit
	add de, hl
	cp de, 0x0078
	jr le, .LHD_SR__c3_lo
	ldw de, 0x0078
	jr t, .LHD_SR__apply
.LHD_SR__c3_lo:
	cps de, 0
	jr gt, .LHD_SR__apply
	lds de, 1
	jr t, .LHD_SR__apply
	; Case 4 (offset 0x004E): head digit * 10
	ld wa, hl
	muls wa, 0x000a
	add bc, wa
	cp bc, 0x000a			; BC >= 10?
	jr lt, .LHD_SR__c4_lo
	ldw bc, 0x000a
	jr t, .LHD_SR__apply
.LHD_SR__c4_lo:
	cps bc, 0
	jr gt, .LHD_SR__apply
	lds bc, 0
	jr t, .LHD_SR__apply
	; Case 5 (offset 0x0069): head unit digit
	add bc, hl
	cp bc, 0x0010			; BC >= 16?
	jr le, .LHD_SR__c5_lo
	ldw bc, 0x0010
	jr t, .LHD_SR__apply
.LHD_SR__c5_lo:
	cps bc, 0
	jr gt, .LHD_SR__apply
	lds bc, 1
.LHD_SR__apply:				; store results
	st16_24 0x22aa5e, xde	; store cylinder
	st16_24 0x22aa60, xbc	; store head
	cpdi16_24 0x22aa5c, 0x0005	; state == 5?
	jr nz, .LHD_SR__fs_init
	; State 5: complete — do table lookup and seek
	ld16_24 xwa, 0x22aa5e
	dec 1, wa
	st16_24 0x23a092, xwa
	ld16_24 xwa, 0x22aa60
	dec 1, wa
	st16_24 0x23a094, xwa
	ld16_24 xwa, 0x23a092
	ld16_24 xbc, 0x23a094
	call HDAE5000_Table_Lookup
	ld iz, hl
	ld wa, iz
	cp wa, 0xffff
	jr z, .LHD_SR__no_match
	; Match found — copy data and seek
	lda_24 xwa, 0x22aa4c
	ld bc, iz
	pushw 0x0002
	lda_24 xde, 0x2e1c96
	calr HDAE5000_HD_Data_Copy
	ld16_24 xbc, 0x23a092
	ld16_24 xde, 0x23a094
	ld wa, iz
	pushw wa                                ; push wa (compact)
	ld xwa, 0x007f0098
	calr HDAE5000_HD_Seek
	jr t, .LHD_SR__fs_init
.LHD_SR__no_match:			; No match — clear and seek with 0xFFFF
	lda_24 xwa, 0x22aa4c
	pushw 0x0002
	lda_24 xde, 0x2e1c96
	lds bc, 0
	calr HDAE5000_HD_Data_Copy
	.byte 0x0b, 0xff, 0xff		; push 0xFFFF
	ld xwa, 0x007f0098
	ldw bc, 0xffff
	ldw de, 0xffff
	calr HDAE5000_HD_Seek
.LHD_SR__fs_init:			; Re-init filesystem display
	pushw 0x0001
	ld16_24 xwa, 0x22aa5e
	ld16_24 xbc, 0x22aa60
	ld16_24 xde, 0x22aa5c
	calr HDAE5000_FS_Init
.LHD_SR__cleanup:
	popw iz                                 ; pop iz (compact)
	retd 0x0002			; return, dealloc 2 bytes
	;
	; Part 2: Event handler A (0x286B72)
.LHD_SR__handlerA:
	dec 0, xsp			; alloc 8 bytes
	push xiz
	ld (xsp + 0x04), xde
	ld (xsp + 0x08), xbc
	ld xiz, xwa
	ld xwa, (xsp + 0x08)		; XWA = event code
	cp xwa, 0x01c00007
	jr z, .LHD_SR__a_evt07
	cp xwa, 0x01c0000d
	jr z, .LHD_SR__a_evt0d
	cp xwa, 0x01e00085
	jrl nz, .LHD_SR__a_exit
	lds32 xhl, 1			; event 0x85: XHL = 1
	jrl t, .LHD_SR__a_epilogue
.LHD_SR__a_evt0d:			; event 0x0D: display update
	ld xwa, xiz
	ld xbc, (xsp + 0x08)
	ld xde, (xsp + 0x04)
	ld32_24 xhl, 0x23a1a2
	ld_sril xhl, (xhl + 0x0e0a)
	ld_sril xhl, (xhl + 0x00dc)
	call (xhl)
	lda_24 xwa, 0x2e2cfe
	ld xbc, xwa
	ld xwa, xiz
	ld xde, xbc
	ld32_24 xbc, 0x23a1a2
	ld_sril xbc, (xbc + 0x0e0a)
	ld_sril xhl, (xbc + 0x0100)
	ld xbc, 0x01c0000f
	call (xhl)
	lds32 xhl, 0
	jrl t, .LHD_SR__a_epilogue
.LHD_SR__a_evt07:			; event 0x07: jump table dispatch
	ld xde, (xsp + 0x04)
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xix, (xwa + 0x0100)
	ld xwa, 0x02600024
	ld xbc, 0x01e00029
	call (xix)
	ld xwa, xhl
	cp xwa, 0x0000000c		; case > 12?
	jrl ugt, .LHD_SR__a_exit
	add xwa, xwa			; index * 2
	add xwa, 0x002e2d04
	ld wa, (xwa)
	lda_24 xix, 0x286c1a		; dispatch base
	.byte 0xf3, 0x07, 0xf0, 0xe0, 0xd8	; jp (XIX + WA)
	; Case 0: re-init FS
	pushw 0x0001
	lds wa, 0
	lds bc, 0
	lds de, 6
	calr HDAE5000_FS_Init
	jrl t, .LHD_SR__a_exit
	; Case 1: toggle read/write direction
	ld xwa, (xsp + 0x04)
	bit 0x07, wa			; bit 7?
	jr nz, .LHD_SR__a_c1_set
	lds wa, 1
	jr t, .LHD_SR__a_c1_push
.LHD_SR__a_c1_set:
	ldw wa, 0xffff
.LHD_SR__a_c1_push:
	pushw wa                                ; push wa
	ld16_24 xwa, 0x22aa5e
	ld16_24 xbc, 0x22aa60
	ld16_24 xde, 0x22aa5c
	calr HDAE5000_HD_Sector_Read	; recursive call
	jrl t, .LHD_SR__a_exit
	; Case 2: sector write (BC=0 or 1)
	ld xwa, (xsp + 0x04)
	bit 0x07, wa
	jr z, .LHD_SR__a_c2b
	ld xwa, xiz
	lds bc, 0
	calr HDAE5000_HD_Sector_Write
	jr t, .LHD_SR__a_exit
.LHD_SR__a_c2b:
	ld xwa, xiz
	lds bc, 1
	calr HDAE5000_HD_Sector_Write
	jr t, .LHD_SR__a_exit
	; Case 3: sector write (BC=2 or 3)
	ld xwa, (xsp + 0x04)
	bit 0x07, wa
	jr z, .LHD_SR__a_c3b
	ld xwa, xiz
	lds bc, 2
	calr HDAE5000_HD_Sector_Write
	jr t, .LHD_SR__a_exit
.LHD_SR__a_c3b:
	ld xwa, xiz
	lds bc, 3
	calr HDAE5000_HD_Sector_Write
	jr t, .LHD_SR__a_exit
	; Case 4: sector write (BC=4 or 5)
	ld xwa, (xsp + 0x04)
	bit 0x07, wa
	jr z, .LHD_SR__a_c4b
	ld xwa, xiz
	lds bc, 4
	calr HDAE5000_HD_Sector_Write
	jr t, .LHD_SR__a_exit
.LHD_SR__a_c4b:
	ld xwa, xiz
	lds bc, 5
	calr HDAE5000_HD_Sector_Write
	jr t, .LHD_SR__a_exit
	; Case 5: sector write (BC=6 or 7)
	ld xwa, (xsp + 0x04)
	bit 0x07, wa
	jr z, .LHD_SR__a_c5b
	ld xwa, xiz
	lds bc, 6
	calr HDAE5000_HD_Sector_Write
	jr t, .LHD_SR__a_exit
.LHD_SR__a_c5b:
	ld xwa, xiz
	lds bc, 7
	calr HDAE5000_HD_Sector_Write
	jr t, .LHD_SR__a_exit
	; Case 6: sector write (BC=8 or 9)
	ld xwa, (xsp + 0x04)
	bit 0x07, wa
	jr z, .LHD_SR__a_c6b
	ld xwa, xiz
	ldw bc, 0x0008
	calr HDAE5000_HD_Sector_Write
	jr t, .LHD_SR__a_exit
.LHD_SR__a_c6b:
	ld xwa, xiz
	ldw bc, 0x0009
	calr HDAE5000_HD_Sector_Write
.LHD_SR__a_exit:			; common exit for handler A
	ld xwa, xiz
	ld xbc, (xsp + 0x08)
	ld xde, (xsp + 0x04)
	ld32_24 xhl, 0x23a1a2
	ld_sril xhl, (xhl + 0x0e0a)
	ld_sril xix, (xhl + 0x00dc)
	call (xix)
.LHD_SR__a_epilogue:
	pop xiz
	inc 0, xsp
	ret
	;
	; Part 3: Event handler B (0x286CED)
.LHD_SR__handlerB:
	dec 0, xsp
	push xiz
	ld (xsp + 0x04), xde
	ld xiz, xbc			; save event code in XIZ
	ld (xsp + 0x08), xwa
	ld xwa, xiz			; XWA = event code
	cp xwa, 0x01c00007
	jrl z, .LHD_SR__b_evt07
	cp xwa, 0x01c0000d
	jr z, .LHD_SR__b_evt0d
	cp xwa, 0x01e00085
	jr z, .LHD_SR__b_evt85
	cp xwa, 0x01c00001
	jrl nz, .LHD_SR__b_exit
	; Event 0x01: table lookup and copy
	ld16_24 xwa, 0x23a092
	ld16_24 xbc, 0x23a094
	call HDAE5000_Table_Lookup
	ld wa, hl
	cp wa, 0xffff
	jr z, .LHD_SR__b_nomatch
	lda_24 xwa, 0x22aa4c
	pushw 0x0002
	ld bc, hl
	lda_24 xde, 0x2e1c96
	calr HDAE5000_HD_Data_Copy
	jrl t, .LHD_SR__b_exit
.LHD_SR__b_nomatch:
	lda_24 xwa, 0x22aa4c
	pushw 0x0002
	lda_24 xde, 0x2e1c96
	lds bc, 0
	calr HDAE5000_HD_Data_Copy
	jrl t, .LHD_SR__b_exit
.LHD_SR__b_evt85:			; event 0x85: XHL = 1
	lds32 xhl, 1
	jrl t, .LHD_SR__b_epilogue
.LHD_SR__b_evt0d:			; event 0x0D: display update
	ld xwa, (xsp + 0x08)
	ld xbc, xiz
	ld xde, (xsp + 0x04)
	ld32_24 xhl, 0x23a1a2
	ld_sril xhl, (xhl + 0x0e0a)
	ld_sril xhl, (xhl + 0x00dc)
	call (xhl)
	lda_24 xwa, 0x2e2d1e
	ld xbc, xwa
	ld xwa, (xsp + 0x08)
	ld xde, xbc
	ld32_24 xbc, 0x23a1a2
	ld_sril xbc, (xbc + 0x0e0a)
	ld_sril xhl, (xbc + 0x0100)
	ld xbc, 0x01c0000f
	call (xhl)
	lds32 xhl, 0
	jrl t, .LHD_SR__b_epilogue
.LHD_SR__b_evt07:			; event 0x07: sector operations
	ld xde, (xsp + 0x04)
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xix, (xwa + 0x0100)
	ld xwa, 0x02600024
	ld xbc, 0x01e00029
	call (xix)
	cp xhl, 0x00000009
	jr z, .LHD_SR__b_check_state
	cp xhl, 0x00000008
	jr nz, .LHD_SR__b_exit
.LHD_SR__b_check_state:
	cpdi16_24 0x22aa5c, 0x0005	; state == 5?
	jr nz, .LHD_SR__b_exit
	; State 5: display manager call + sector read
	pushw 0x0001
	ld xwa, 0x007f008f
	push xwa
	ld16_24 xwa, 0x23a092
	ld16_24 xbc, 0x23a094
	ld16_24 xde, 0x22aa4c
	calr HDAE5000_Display_Manager
	pushw 0x0001
	lds wa, 0
	lds bc, 0
	lds de, 6
	calr HDAE5000_FS_Init
	cpi8_24 0x229dac, 0x02
	jr nz, .LHD_SR__b_exit
	ld16_24 xwa, 0x22aa4c
	and wa, 0x0100
	cp wa, 0x0100
	jr nz, .LHD_SR__b_exit
	; Flag set: register display handler
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)
	ld xwa, 0x007f02f0
	ld xbc, 0x01c00001
	lds32 xde, 0
	call (xhl)
.LHD_SR__b_exit:			; common exit
	ld xwa, (xsp + 0x08)
	ld xbc, xiz
	ld xde, (xsp + 0x04)
	ld32_24 xhl, 0x23a1a2
	ld_sril xhl, (xhl + 0x0e0a)
	ld_sril xix, (xhl + 0x00dc)
	call (xix)
.LHD_SR__b_epilogue:
	pop xiz
	inc 0, xsp
	ret

HDAE5000_HD_Sector_Write:	; 0x286E50 (646 bytes)
	; Write sectors to HD; accesses 0x229DAA, 0x229DAC
	; --- Prologue ---
	push xiz				; 3e
	ld	qiz, 0

	; --- Switch on state variable at 0x22AA5C ---
	ld16_24 xwa, 0x22aa5c		; d2 5c aa 22 20 — ld wa, (0x22aa5c)
	cps wa, 4				; d8 dc
	jrl z, .Lsw_case4			; 76 xx xx
	cps wa, 3				; d8 db
	jrl z, .Lsw_case3			; 76 xx xx
	cps wa, 2				; d8 da
	jr z, .Lsw_case2			; 66 xx
	cps wa, 1				; d8 d9
	jr z, .Lsw_case1			; 66 xx
	cps wa, 0				; d8 d8
	jrl nz, .Lsw_exit			; 7e xx xx

	; === Case 0: initialize cylinder from BC*100, set state=1 ===
	ld wa, bc				; d9 88
	mul wa, 0x0064				; d8 08 64 00
	st16_24 0x22aa5e, xwa			; f2 5e aa 22 50 — ld (0x22aa5e), wa
	sti16_24 0x22aa60, 0x0000		; f2 60 aa 22 02 00 00
	sti16_24 0x22aa5c, 0x0001		; f2 5c aa 22 02 01 00
	pushw 0x0001
	ld16_24 xwa, 0x22aa5e		; d2 5e aa 22 20
	ld16_24 xbc, 0x22aa60		; d2 60 aa 22 21
	ld16_24 xde, 0x22aa5c		; d2 5c aa 22 22
	calr HDAE5000_FS_Init			; 1e xx xx
	ld	qiz, hl
	jrl t, .Lsw_exit			; 78 xx xx

	; === Case 1: add BC*10 to cylinder, set state=2 ===
.Lsw_case1:					; 0x286EA4
	ld wa, bc				; d9 88
	mul wa, 0x000a				; d8 08 0a 00
	adddm16_24 0x22aa5e, xwa		; d2 5e aa 22 88
	sti16_24 0x22aa5c, 0x0002		; f2 5c aa 22 02 02 00
	pushw 0x0001
	ld16_24 xwa, 0x22aa5e		; d2 5e aa 22 20
	ld16_24 xbc, 0x22aa60		; d2 60 aa 22 21
	ld16_24 xde, 0x22aa5c		; d2 5c aa 22 22
	calr HDAE5000_FS_Init			; 1e xx xx
	ld	qiz, hl
	jrl t, .Lsw_exit			; 78 xx xx

	; === Case 2: add BC to cylinder, set state=3 ===
.Lsw_case2:					; 0x286ED1
	adddm16_24 0x22aa5e, xbc		; d2 5e aa 22 89
	sti16_24 0x22aa5c, 0x0003		; f2 5c aa 22 02 03 00
	pushw 0x0001
	ld16_24 xwa, 0x22aa5e		; d2 5e aa 22 20
	ld16_24 xbc, 0x22aa60		; d2 60 aa 22 21
	ld16_24 xde, 0x22aa5c		; d2 5c aa 22 22
	calr HDAE5000_FS_Init			; 1e xx xx
	ld	qiz, hl
	jrl t, .Lsw_exit			; 78 xx xx

	; === Case 3: set head from BC*10, set state=4 ===
.Lsw_case3:					; 0x286EF8
	ld wa, bc				; d9 88
	mul wa, 0x000a				; d8 08 0a 00
	st16_24 0x22aa60, xwa			; f2 60 aa 22 50
	sti16_24 0x22aa5c, 0x0004		; f2 5c aa 22 02 04 00
	pushw 0x0001
	ld16_24 xwa, 0x22aa5e		; d2 5e aa 22 20
	ld16_24 xbc, 0x22aa60		; d2 60 aa 22 21
	ld16_24 xde, 0x22aa5c		; d2 5c aa 22 22
	calr HDAE5000_FS_Init			; 1e xx xx
	ld	qiz, hl
	jrl t, .Lsw_exit			; 78 xx xx

	; === Case 4: add BC to head, set state=5, then process ===
.Lsw_case4:					; 0x286F25
	adddm16_24 0x22aa60, xbc		; d2 60 aa 22 89
	sti16_24 0x22aa5c, 0x0005		; f2 5c aa 22 02 05 00
	pushw 0x0001
	ld16_24 xwa, 0x22aa5e		; d2 5e aa 22 20
	ld16_24 xbc, 0x22aa60		; d2 60 aa 22 21
	ld16_24 xde, 0x22aa5c		; d2 5c aa 22 22
	calr HDAE5000_FS_Init			; 1e xx xx
	ld	qiz, hl

	; --- After all cases: check result ---
	ld	wa, qiz
	cps wa, 0				; d8 d8
	jrl nz, .Lsw_exit			; 7e xx xx — error → exit

	; --- Compute sector address and look up in table ---
	ld16_24 xwa, 0x22aa5e		; d2 5e aa 22 20 — cylinder
	dec 1, wa				; d8 69
	st16_24 0x23a092, xwa			; f2 92 a0 23 50
	ld16_24 xwa, 0x22aa60		; d2 60 aa 22 20 — head
	dec 1, wa				; d8 69
	st16_24 0x23a094, xwa			; f2 94 a0 23 50
	ld16_24 xwa, 0x23a092		; d2 92 a0 23 20
	ld16_24 xbc, 0x23a094		; d2 94 a0 23 21
	call HDAE5000_Table_Lookup		; 1d b3 03 29
	ld iz, hl				; db 8e
	ld wa, iz				; de 88
	cp wa, 0xffff				; d8 cf ff ff
	jr z, .Lsw_lookup_notfound		; 66 xx

	; --- Found: copy data and seek ---
.Lsw_lookup_found:				; 0x286F81
	lda_24 xwa, 0x22aa4c			; f2 4c aa 22 30
	ld bc, iz				; de 89
	pushw 0x0002
	lda_24 xde, 0x2e1c96			; f2 96 1c 2e 32
	calr HDAE5000_HD_Data_Copy		; 1e xx xx
	ld16_24 xbc, 0x23a092		; d2 92 a0 23 21
	ld16_24 xde, 0x23a094		; d2 94 a0 23 22
	ld wa, iz				; de 88
	pushw wa                                ; push wa (compact 16-bit)
	ld xwa, 0x007f0098			; 40 98 00 7f 00
	calr HDAE5000_HD_Seek			; 1e xx xx
	jr t, .Lsw_after_lookup			; 68 xx

	; --- Not found: copy default data and seek with -1 ---
.Lsw_lookup_notfound:				; 0x286FAA
	lda_24 xwa, 0x22aa4c			; f2 4c aa 22 30
	pushw 0x0002
	lda_24 xde, 0x2e1c96			; f2 96 1c 2e 32
	lds bc, 0				; d9 a8
	calr HDAE5000_HD_Data_Copy		; 1e xx xx
	pushw 0xffff
	ld xwa, 0x007f0098			; 40 98 00 7f 00
	ldw bc, 0xffff				; 31 ff ff
	ldw de, 0xffff				; 32 ff ff
	calr HDAE5000_HD_Seek			; 1e xx xx

	; --- After table lookup: check sectors per track ---
.Lsw_after_lookup:				; 0x286FCD
	cpi8_24 0x229daa, 0x02			; c2 aa 9d 22 3f 02
	jr nz, .Lsw_exit			; 6e xx
	; Sectors per track == 2: do display and FS operations
	pushw 0x0001
	ld xwa, 0x007f008f			; 40 8f 00 7f 00
	push xwa				; 38
	ld16_24 xwa, 0x23a092		; d2 92 a0 23 20
	ld16_24 xbc, 0x23a094		; d2 94 a0 23 21
	ld16_24 xde, 0x22aa4c		; d2 4c aa 22 22
	calr HDAE5000_Display_Manager		; 1e xx xx
	pushw 0x0001
	lds wa, 0				; d8 a8
	lds bc, 0				; d9 a8
	lds de, 6				; da ae
	calr HDAE5000_FS_Init			; 1e xx xx
	; Check second disk flag
	cpi8_24 0x229dac, 0x02			; c2 ac 9d 22 3f 02
	jr nz, .Lsw_exit			; 6e xx
	; Check bit 8 of aa4c entry
	ld16_24 xwa, 0x22aa4c		; d2 4c aa 22 20
	and wa, 0x0100				; d8 cc 00 01
	cp wa, 0x0100				; d8 cf 00 01
	jr nz, .Lsw_exit			; 6e xx
	; Register event: format complete
	ld32_24 xwa, 0x23a1a2		; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
	ld_sril xhl, (xwa + 0x0124)             ; e3 e1 24 01 23
	ld xwa, 0x007f02f0			; 40 f0 02 7f 00
	ld xbc, 0x01c00001			; 41 01 00 c0 01
	lds32 xde, 0				; ea a8
	call (xhl)				; b3 e8

	; === Exit: check QIZ result ===
.Lsw_exit:					; 0x287030
	ld	wa, qiz
	cp wa, 0xfffe				; d8 cf fe ff
	jr z, .Lsw_err_fffe			; 66 xx
	cp wa, 0xffff				; d8 cf ff ff
	jrl nz, .Lsw_done			; 7e xx xx

	; --- Error 0xFFFF: register error + timer ---
	ld32_24 xwa, 0x23a1a2		; e2 a2 a1 23 20
	ld_sril xwa, (xwa + 0x0e0a)             ; e3 e1 0a 0e 20
