	ld16_24 xde, 0x22aa4c
	calr HDAE5000_Display_Scroll
	lds wa, 0
	lds bc, 0
	calr HDAE5000_HD_Read_Write
	jr t, .LFSD__hC_default
.LFSD__hC_key_67:			; Key 6 or 7: close display
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)
	ld xwa, 0x007f0018
	ld xbc, 0x01c00001
	lds32 xde, 0
	call (xhl)
.LFSD__hC_default:			; Default: pass-through to registered handler
	ld xwa, (xsp + 0x08)
	ld xbc, xiz
	ld xde, (xsp + 0x04)
	ld32_24 xhl, 0x23a1a2
	ld_sril xhl, (xhl + 0x0e0a)
	ld_sril xix, (xhl + 0x00dc)
	call (xix)
.LFSD__hC_exit:
	pop xiz
	inc 0, xsp
	ret

HDAE5000_FS_Entry_Lookup:	; 0x28A2F0 (739 bytes)
	; Look up a file entry in the filesystem
	; Part 1: 9 lookup blocks — read byte, lookup table, call handler
	; Block 1: address 0x22ABE8, command 0x007F01CF
	ld8_24 xwa, 0x22abe8
	extz wa
	sla wa, 2
	lda_24 xbc, 0x2e1e14
	ld_sril3 xde, 0x07, 0xe4, 0xe0	; ld XDE, (XBC + WA)
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)             ; ld XWA, (XWA + 0x0E0A)
	ld_sril xhl, (xwa + 0x0104)             ; ld XHL, (XWA + 0x0104)
	ld xwa, 0x007f01cf
	ld xbc, 0x01c0000f
	call (xhl)
	; Block 2: address 0x22ABE9, command 0x007F01D0
	ld8_24 xwa, 0x22abe9
	extz wa
	sla wa, 2
	lda_24 xbc, 0x2e1e14
	ld_sril3 xde, 0x07, 0xe4, 0xe0
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)
	ld xwa, 0x007f01d0
	ld xbc, 0x01c0000f
	call (xhl)
	; Block 3: address 0x22ABEA, command 0x007F01D1
	ld8_24 xwa, 0x22abea
	extz wa
	sla wa, 2
	lda_24 xbc, 0x2e1e14
	ld_sril3 xde, 0x07, 0xe4, 0xe0
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)
	ld xwa, 0x007f01d1
	ld xbc, 0x01c0000f
	call (xhl)
	; Block 4: address 0x22ABEB, command 0x007F01D2
	ld8_24 xwa, 0x22abeb
	extz wa
	sla wa, 2
	lda_24 xbc, 0x2e1e14
	ld_sril3 xde, 0x07, 0xe4, 0xe0
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)
	ld xwa, 0x007f01d2
	ld xbc, 0x01c0000f
	call (xhl)
	; Block 5: address 0x22ABEC, command 0x007F01D3
	ld8_24 xwa, 0x22abec
	extz wa
	sla wa, 2
	lda_24 xbc, 0x2e1e14
	ld_sril3 xde, 0x07, 0xe4, 0xe0
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)
	ld xwa, 0x007f01d3
	ld xbc, 0x01c0000f
	call (xhl)
	; Block 6: address 0x22ABED, command 0x007F01D4
	ld8_24 xwa, 0x22abed
	extz wa
	sla wa, 2
	lda_24 xbc, 0x2e1e14
	ld_sril3 xde, 0x07, 0xe4, 0xe0
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)
	ld xwa, 0x007f01d4
	ld xbc, 0x01c0000f
	call (xhl)
	; Block 7: address 0x22ABEE, command 0x007F01D5
	ld8_24 xwa, 0x22abee
	extz wa
	sla wa, 2
	lda_24 xbc, 0x2e1e14
	ld_sril3 xde, 0x07, 0xe4, 0xe0
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)
	ld xwa, 0x007f01d5
	ld xbc, 0x01c0000f
	call (xhl)
	; Block 8: address 0x22ABEF, command 0x007F01D6
	ld8_24 xwa, 0x22abef
	extz wa
	sla wa, 2
	lda_24 xbc, 0x2e1e14
	ld_sril3 xde, 0x07, 0xe4, 0xe0
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)
	ld xwa, 0x007f01d6
	ld xbc, 0x01c0000f
	call (xhl)
	; Block 9: address 0x22ABF0, command 0x007F01E9 (tail call)
	ld8_24 xwa, 0x22abf0
	extz wa
	sla wa, 2
	lda_24 xbc, 0x2e1e14
	ld_sril3 xde, 0x07, 0xe4, 0xe0
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0104)
	ld xwa, 0x007f01e9
	ld xbc, 0x01c0000f
	jp (xhl)			; tail call (not call)
	;
	; Part 2: Event handler (0x28A497) — dispatches on event codes
.LFS_EL__handler:
	dec 0, xsp			; allocate 8 bytes
	push xiz
	ld (xsp + 0x04), xde		; save XDE to stack
	ld xiz, xbc			; save event code in XIZ
	ld (xsp + 0x08), xwa		; save XWA to stack
	ld xwa, xiz			; XWA = event code
	cp xwa, 0x01c00007		; event 0x01C00007?
	jr z, .LFS_EL__evt_07
	cp xwa, 0x01c0000d		; event 0x01C0000D?
	jr z, .LFS_EL__evt_0d
	cp xwa, 0x01e00085		; event 0x01E00085?
	jrl nz, .LFS_EL__exit		; no match → exit
	lds32 xhl, 1			; XHL = 1
	jrl t, .LFS_EL__epilogue
.LFS_EL__evt_0d:			; handler for event 0x0D
	ld xwa, (xsp + 0x08)		; restore XWA
	ld xbc, xiz
	ld xde, (xsp + 0x04)		; restore XDE
	ld32_24 xhl, 0x23a1a2
	ld_sril xhl, (xhl + 0x0e0a)             ; ld XHL, (XHL + 0x0E0A)
	ld_sril xhl, (xhl + 0x00dc)             ; ld XHL, (XHL + 0x00DC)
	call (xhl)
	lda_24 xwa, 0x2e2f62		; status display data
	ld xbc, xwa
	ld xwa, (xsp + 0x08)
	ld xde, xbc
	ld32_24 xbc, 0x23a1a2
	ld_sril xbc, (xbc + 0x0e0a)             ; ld XBC, (XBC + 0x0E0A)
	ld_sril xhl, (xbc + 0x0100)             ; ld XHL, (XBC + 0x0100)
	ld xbc, 0x01c0000f
	call (xhl)
	lds32 xhl, 0
	jrl t, .LFS_EL__epilogue
.LFS_EL__evt_07:			; handler for event 0x07
	ld xde, (xsp + 0x04)
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xix, (xwa + 0x0100)             ; ld XIX, (XWA + 0x0100)
	ld xwa, 0x02600024
	ld xbc, 0x01e00029
	call (xix)
	; Check return value in XHL
	cp xhl, 0x0000000b
	jr z, .LFS_EL__case_0b
	cp xhl, 0x0000000a
	jr z, .LFS_EL__case_0a
	cp xhl, 0x00000008
	jr nz, .LFS_EL__exit
	; Case 0x08: delete file entry
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0124)             ; ld XHL, (XWA + 0x0124)
	ld xwa, 0x007f01fb
	ld xbc, 0x01c00001
	lds32 xde, 0
	call (xhl)
	jr t, .LFS_EL__exit
.LFS_EL__case_0a:			; Case 0x0A: copy file
	ld16_24 xwa, 0x23a092
	ld16_24 xbc, 0x23a094
	call HDAE5000_Table_Lookup
	ld wa, hl
	cp wa, 0xffff
	jr z, .LFS_EL__0a_skip
	lda_24 xwa, 0x22abe6
	pushw 0x0002
	ld bc, hl
	lda_24 xde, 0x2e1e08
	calr HDAE5000_HD_Data_Copy
.LFS_EL__0a_skip:
	calr HDAE5000_FS_Entry_Lookup	; recursive call
	jr t, .LFS_EL__exit
.LFS_EL__case_0b:			; Case 0x0B: save file
	ld16_24 xwa, 0x23a092
	ld16_24 xbc, 0x23a094
	call HDAE5000_Table_Lookup
	ld wa, hl
	cp wa, 0xffff
	jr z, .LFS_EL__0b_skip
	lda_24 xwa, 0x22abe6
	pushw 0x0001
	ld bc, hl
	lda_24 xde, 0x2e1e08
	calr HDAE5000_HD_Data_Copy
.LFS_EL__0b_skip:
	sti16_24 0x22abe6, 0x0000	; clear entry
	calr HDAE5000_FS_Entry_Lookup	; recursive call
.LFS_EL__exit:				; common exit path
	ld xwa, (xsp + 0x08)		; restore registers
	ld xbc, xiz
	ld xde, (xsp + 0x04)
	ld32_24 xhl, 0x23a1a2
	ld_sril xhl, (xhl + 0x0e0a)             ; ld XHL, (XHL + 0x0E0A)
	ld_sril xix, (xhl + 0x00dc)             ; ld XIX, (XHL + 0x00DC)
	call (xix)
.LFS_EL__epilogue:
	pop xiz
	inc 0, xsp			; deallocate 8 bytes
	ret

; --- Display, Menu, and Utility Routines ---
HDAE5000_Display_Update_Offset:	; 0x28A5D3 (1612 bytes)
	; Part 1: Table lookup + data copy utility (68 bytes)
	ld16_24 xwa, 0x23a092		; WA = cylinder
	ld16_24 xbc, 0x23a094	; BC = head
	call HDAE5000_Table_Lookup
	ld wa, hl
	cp wa, 0xffff
	jr z, .LDUO__not_found
	; Found — copy data
	lda_24 xwa, 0x22abe6
	pushw 0x0002
	ld bc, hl
	lda_24 xde, 0x2e1e08
	calr HDAE5000_HD_Data_Copy
	jr t, .LDUO__done_p1
.LDUO__not_found:
	lda_24 xwa, 0x22abe6
	pushw 0x0002
	lda_24 xde, 0x2e1e08
	lds bc, 0
	calr HDAE5000_HD_Data_Copy
.LDUO__done_p1:
	sti16_24 0x22abe6, 0x0000
	ret
	;
	; Part 2: Handler A (0x28A617) — event handler with stack frame
.LDUO__handlerA:
	dec 4, xsp			; alloc 16 bytes
	push xiz
	ld (xsp + 0x04), xwa
	ld xwa, xbc
	cp xwa, 0x01e00082
	jr z, .LDUO__hA_ev82
	sub xwa, 0x01e0003e		; normalize event code
	cp xwa, 0x00000000
	jr lt, .LDUO__hA_default
	cp xwa, 0x00000009
	jr gt, .LDUO__hA_default
	add xwa, xwa
	add xwa, 0x002e2f6c		; jump table
	ld wa, (xwa)
	lda_24 xix, 0x28a651		; dispatch base
	.byte 0xf3, 0x07, 0xf0, 0xe0, 0xd8	; jp (XIX + WA)
	; Case 0: full lookup
	ld xiz, xde
	ld16_24 xwa, 0x23a092
	ld16_24 xbc, 0x23a094
	call HDAE5000_Calculate_Row_Address
	push xhl
	pushw 0x002e
	pushw 0x2f68
	ld xwa, (xiz + 0x12)
	push xwa
	call 0x29abd8
	lda xsp, (xsp + 0x0c)
	ld xhl, (xsp + 0x04)
	jr t, .LDUO__hA_exit
	; Case 1
	lds32 xhl, 1
	jr t, .LDUO__hA_exit
	; Case 2
	lds32 xhl, 1
	jr t, .LDUO__hA_exit
	; Case 3
	lds32 xhl, 0
	jr t, .LDUO__hA_exit
	; Case 4
	lds32 xhl, 0
	jr t, .LDUO__hA_exit
	; Case 5
	lda_24 xhl, 0x22aa57
	jr t, .LDUO__hA_exit
	; Case 6
	lds32 xhl, 1
	jr t, .LDUO__hA_exit
.LDUO__hA_ev82:
	lds32 xhl, 0
	jr t, .LDUO__hA_exit
.LDUO__hA_default:
	lds32 xhl, 0
.LDUO__hA_exit:
	pop xiz
	inc 4, xsp
	ret
	;
	; Part 3: Handler B (0x28A69D) — digit callback for slot 0 (0x22ABE8)
.LDUO__handlerB:
	push xiz
	ld xiz, xwa
	ld xwa, xbc
	cp xwa, 0x01e00082
	jr z, .LDUO__hB_ev82
	sub xwa, 0x01e0003e
	cp xwa, 0x00000000
	jr lt, .LDUO__hB_default
	cp xwa, 0x00000009
	jr gt, .LDUO__hB_default
	add xwa, xwa
	add xwa, 0x002e2f84
	ld wa, (xwa)
	lda_24 xix, 0x28a6d4
	.byte 0xf3, 0x07, 0xf0, 0xe0, 0xd8	; jp (XIX + WA)
	; Case 0: index + format + display
	ld xwa, (xde + 0x0e)
	sll xwa, 2
	ld xbc, 0x002e1e14
	add xbc, xwa
	ld xwa, (xbc)
	push xwa
	pushw 0x002e
	pushw 0x2f80
	ld xwa, (xde + 0x12)
	push xwa
	call 0x29abd8
	lda xsp, (xsp + 0x0c)
	ld xhl, xiz
	jr t, .LDUO__hB_exit
	; Case 1
	lds32 xhl, 1
	jr t, .LDUO__hB_exit
	; Case 2
	lds32 xhl, 1
	jr t, .LDUO__hB_exit
	; Case 3: conditional on (0x22abe8)
	lds32 xhl, 2
	cpi8_24 0x22abe8, 0x00
	jr nz, .LDUO__hB_c3_nz
	lds32 xhl, 0
.LDUO__hB_c3_nz:
	jr t, .LDUO__hB_exit
	; Case 4: conditional on (0x22abe8)
	lds32 xhl, 1
	cpi8_24 0x22abe8, 0x00
	jr nz, .LDUO__hB_c4_nz
	lds32 xhl, 0
.LDUO__hB_c4_nz:
	jr t, .LDUO__hB_exit
	; Case 5
	lda_24 xhl, 0x22abe8
	jr t, .LDUO__hB_exit
	; Case 6
	lds32 xhl, 1
	jr t, .LDUO__hB_exit
.LDUO__hB_ev82:
	lda_24 xwa, 0x22abe6
	calr HDAE5000_HD_Buffer_Init
	lds32 xhl, 0
	jr t, .LDUO__hB_exit
.LDUO__hB_default:
	lds32 xhl, 0
.LDUO__hB_exit:
	pop xiz
	ret
	;
	; Part 4: Handler C (0x28A738) — slot 1 (0x22ABE9)
.LDUO__handlerC:
	push xiz
	ld xiz, xwa
	ld xwa, xbc
	cp xwa, 0x01e00082
	jr z, .LDUO__hC_ev82
	sub xwa, 0x01e0003e
	cp xwa, 0x00000000
	jr lt, .LDUO__hC_default
	cp xwa, 0x00000009
	jr gt, .LDUO__hC_default
	add xwa, xwa
	add xwa, 0x002e2f9c
	ld wa, (xwa)
	lda_24 xix, 0x28a76f
	.byte 0xf3, 0x07, 0xf0, 0xe0, 0xd8	; jp (XIX + WA)
	; Case 0
	ld xwa, (xde + 0x0e)
	sll xwa, 2
	ld xbc, 0x002e1e14
	add xbc, xwa
	ld xwa, (xbc)
	push xwa
	pushw 0x002e
	pushw 0x2f98
	ld xwa, (xde + 0x12)
	push xwa
	call 0x29abd8
	lda xsp, (xsp + 0x0c)
	ld xhl, xiz
	jr t, .LDUO__hC_exit
	; Case 1
	lds32 xhl, 1
	jr t, .LDUO__hC_exit
	; Case 2
	lds32 xhl, 1
	jr t, .LDUO__hC_exit
	; Case 3
	lds32 xhl, 2
	cpi8_24 0x22abe9, 0x00
	jr nz, .LDUO__hC_c3_nz
	lds32 xhl, 0
.LDUO__hC_c3_nz:
	jr t, .LDUO__hC_exit
	; Case 4
	lds32 xhl, 1
	cpi8_24 0x22abe9, 0x00
	jr nz, .LDUO__hC_c4_nz
	lds32 xhl, 0
.LDUO__hC_c4_nz:
	jr t, .LDUO__hC_exit
	; Case 5
	lda_24 xhl, 0x22abe9
	jr t, .LDUO__hC_exit
	; Case 6
	lds32 xhl, 1
	jr t, .LDUO__hC_exit
.LDUO__hC_ev82:
	lda_24 xwa, 0x22abe6
	calr HDAE5000_HD_Buffer_Init
	lds32 xhl, 0
	jr t, .LDUO__hC_exit
.LDUO__hC_default:
	lds32 xhl, 0
.LDUO__hC_exit:
	pop xiz
	ret
	;
	; Part 5: Handler D (0x28A7D3) — slot 2 (0x22ABEA)
.LDUO__handlerD:
	push xiz
	ld xiz, xwa
	ld xwa, xbc
	cp xwa, 0x01e00082
	jr z, .LDUO__hD_ev82
	sub xwa, 0x01e0003e
	cp xwa, 0x00000000
	jr lt, .LDUO__hD_default
	cp xwa, 0x00000009
	jr gt, .LDUO__hD_default
	add xwa, xwa
	add xwa, 0x002e2fb4
	ld wa, (xwa)
	lda_24 xix, 0x28a80a
	.byte 0xf3, 0x07, 0xf0, 0xe0, 0xd8	; jp (XIX + WA)
	; Case 0
	ld xwa, (xde + 0x0e)
	sll xwa, 2
	ld xbc, 0x002e1e14
	add xbc, xwa
	ld xwa, (xbc)
	push xwa
	pushw 0x002e
	pushw 0x2fb0
	ld xwa, (xde + 0x12)
	push xwa
	call 0x29abd8
	lda xsp, (xsp + 0x0c)
	ld xhl, xiz
	jr t, .LDUO__hD_exit
	; Case 1
	lds32 xhl, 1
	jr t, .LDUO__hD_exit
	; Case 2
	lds32 xhl, 1
	jr t, .LDUO__hD_exit
	; Case 3
	lds32 xhl, 2
	cpi8_24 0x22abea, 0x00
	jr nz, .LDUO__hD_c3_nz
	lds32 xhl, 0
.LDUO__hD_c3_nz:
	jr t, .LDUO__hD_exit
	; Case 4
	lds32 xhl, 1
	cpi8_24 0x22abea, 0x00
	jr nz, .LDUO__hD_c4_nz
	lds32 xhl, 0
.LDUO__hD_c4_nz:
	jr t, .LDUO__hD_exit
	; Case 5
	lda_24 xhl, 0x22abea
	jr t, .LDUO__hD_exit
	; Case 6
	lds32 xhl, 1
	jr t, .LDUO__hD_exit
.LDUO__hD_ev82:
	lda_24 xwa, 0x22abe6
	calr HDAE5000_HD_Buffer_Init
	lds32 xhl, 0
	jr t, .LDUO__hD_exit
.LDUO__hD_default:
	lds32 xhl, 0
.LDUO__hD_exit:
	pop xiz
	ret
	;
	; Part 6: Handler E (0x28A86E) — slot 3 (0x22ABEB)
.LDUO__handlerE:
	push xiz
	ld xiz, xwa
	ld xwa, xbc
	cp xwa, 0x01e00082
