	ld xwa, (xbc)
	push xwa
	pushw 0x002e
	pushw 0x2fc8
	ld xwa, (xde + 0x12)
	push xwa
	call 0x29abd8
	lda xsp, (xsp + 0x0c)
	ld xhl, xiz
	jr t, .LDUO__hE_exit
	; Case 1
	lds32 xhl, 1
	jr t, .LDUO__hE_exit
	; Case 2
	lds32 xhl, 1
	jr t, .LDUO__hE_exit
	; Case 3
	lds32 xhl, 2
	cpi8_24 0x22abeb, 0x00
	jr nz, .LDUO__hE_c3_nz
	lds32 xhl, 0
.LDUO__hE_c3_nz:
	jr t, .LDUO__hE_exit
	; Case 4
	lds32 xhl, 1
	cpi8_24 0x22abeb, 0x00
	jr nz, .LDUO__hE_c4_nz
	lds32 xhl, 0
.LDUO__hE_c4_nz:
	jr t, .LDUO__hE_exit
	; Case 5
	lda_24 xhl, 0x22abeb
	jr t, .LDUO__hE_exit
	; Case 6
	lds32 xhl, 1
	jr t, .LDUO__hE_exit
.LDUO__hE_ev82:
