	ld xbc, xwa
	ld wa, iz
	lds de, 0
	call HDAE5000_Copy_Display_Cell_90
	cp hl, 0xFFFF
	jr z, .Lmc_alt
	; --- Direct dispatch ---
	ld xwa, (xsp + 20)
	ld32_24 xbc, 0x23a1a2
	ld_sril xbc, (xbc + 0x0e0a)
	ld_sril xhl, (xbc + 0x0104)             ; ld XHL, (XBC + 0x0104)
	ld xbc, 0x01C00001
	lds32 xde, 0
	call (xhl)
	jr t, .Lmc_finish
.Lmc_alt:
	; --- Alternate handler ---
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0100)
	ld xwa, 0x007F0297
	ld xbc, 0x01C00001
	lds32 xde, 0
	call (xhl)
	ld xbc, (xsp + 20)
	ld xwa, 0x007F0298
	calr HDAE5000_UI_Main_Handler
	; --- Register display handlers ---
	ld xwa, 0x01CA0002
	push xwa
	ld xwa, (xsp + 24)
	push xwa
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0418)             ; ld XHL, (XWA + 0x0418)
	ld xwa, 0x0000014D
	ld xbc, 0x007F0299
	ld xde, 0xFFFFFFFF
	call (xhl)
	ld xwa, 0x01CA0002
	push xwa
	ld xwa, (xsp + 24)
	push xwa
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x0410)             ; ld XHL, (XWA + 0x0410)
	ld xwa, 0x0000014D
	ld xbc, 0x007F0299
	ld xde, 0xFFFFFFFF
