	.byte 0xeb, 0xee, 0x03                 ; sll 0x03,XHL
	add	xhl, xwa
	.byte 0xeb, 0xee, 0x04                 ; sll 0x04,XHL
	add	xhl, xbc
	lda_24 xwa, 0x225822
	ld	xbc, xwa
	add	xbc, xhl
	ld	a, (xde+5)
	.byte 0xb1, 0x41                       ; ld (XBC),A
	ld	wa, (xsp+4)
	.byte 0x1e, 0x6f, 0x3d                 ; calr 0x293e2e
	.byte 0x0f, 0x02, 0x00                 ; retd 0x0002

	extz xbc                                ; extz XBC
	extz xwa
	ld	xhl, xwa
	.byte 0xeb, 0xee, 0x03                 ; sll 0x03,XHL
	add	xhl, xwa
	.byte 0xeb, 0xee, 0x04                 ; sll 0x04,XHL
	add	xhl, xbc
	lda_24 xwa, 0x2257c2
	ld	xbc, xwa
	add	xbc, xhl
	ld	a, e
	inc	1, a
	.byte 0xb1, 0x41                       ; ld (XBC),A
	lds	hl, 0
	ret

	extz xbc                                ; extz XBC
	extz xwa
	ld	xhl, xwa
	.byte 0xeb, 0xee, 0x03                 ; sll 0x03,XHL
	add	xhl, xwa
	.byte 0xeb, 0xee, 0x04                 ; sll 0x04,XHL
	add	xhl, xbc
	lda_24 xwa, 0x2257e2
	ld	xbc, xwa
	add	xbc, xhl
	ld	a, e
	inc	1, a
	.byte 0xb1, 0x41                       ; ld (XBC),A
	lds	hl, 0
	ret

	dec	4, xsp
	pushw iz                                ; push IZ
	.byte 0xbf, 0x02, 0x45                 ; ld (XSP+0x02),E
	ld	iz, bc
	ld (xsp + 0x04), wa                     ; ld (XSP+0x04),WA
	ld	wa, (xsp+4)
	ld	bc, iz
	.byte 0x1e, 0x98, 0xfa                 ; calr 0x28fbb1
	ld	wa, hl
	cp	wa, 0xffff
	jr z, .LCIB_0144                       ; [66 23] jr Z,0x290144
	ld	bc, iz
	extz xbc                                ; extz XBC
	ld	wa, (xsp+4)
	extz xwa
	ld	xde, xwa
	.byte 0xea, 0xee, 0x03                 ; sll 0x03,XDE
	add	xde, xwa
	.byte 0xea, 0xee, 0x04                 ; sll 0x04,XDE
	add	xde, xbc
	lda_24 xwa, 0x225802
	ld	xbc, xwa
	add	xbc, xde
	ld	a, (xsp+2)
	.byte 0xb1, 0x41                       ; ld (XBC),A
.LCIB_0144:
	popw iz                                 ; pop IZ
	inc 4, xsp                              ; inc 4,XSP
	ret

	dec	4, xsp
	pushw iz                                ; push IZ
	.byte 0xbf, 0x02, 0x45                 ; ld (XSP+0x02),E
	ld	iz, bc
	ld (xsp + 0x04), wa                     ; ld (XSP+0x04),WA
	ld	wa, (xsp+4)
	ld	bc, iz
	.byte 0x1e, 0x56, 0xfa                 ; calr 0x28fbb1
	ld	wa, hl
	cp	wa, 0xffff
	jr z, .LCIB_0186                       ; [66 23] jr Z,0x290186
	ld	bc, iz
	extz xbc                                ; extz XBC
	ld	wa, (xsp+4)
	extz xwa
	ld	xde, xwa
	.byte 0xea, 0xee, 0x03                 ; sll 0x03,XDE
	add	xde, xwa
	.byte 0xea, 0xee, 0x04                 ; sll 0x04,XDE
	add	xde, xbc
	lda_24 xwa, 0x225822
	ld	xbc, xwa
	add	xbc, xde
	ld	a, (xsp+2)
	.byte 0xb1, 0x41                       ; ld (XBC),A
.LCIB_0186:
	popw iz                                 ; pop IZ
	inc 4, xsp                              ; inc 4,XSP
	ret


HDAE5000_Table_Calc_Offset:	; 0x29018A (553 bytes)
	; Check 9 table slots for availability (-1 = free)
	; WA = row index, BC = column index
	; Returns HL=0 if any slot occupied, HL=0xFFFF if all free
	dec 4, xsp
	push xiz
	ld (xsp + 4), bc		; save column
	ld (xsp + 6), wa		; save row
	; --- Slot 0: base 0x201656 ---
	ld wa, (xsp + 4)
	extz xwa
	ld xbc, 0x0000004C
	call HDAE5000_Multiply
	ld xiz, xhl			; XIZ = column * 0x4C
	ld wa, (xsp + 6)
	extz xwa
	ld xbc, 0x000004C0
	call HDAE5000_Multiply
	add xhl, 0x00000780		; + base offset
	add xhl, xiz			; + column offset
	lda_24 xwa, 0x201656                  ; 0x201656
	add xwa, xhl
	ld xwa, (xwa)			; load slot value
	cp xwa, 0xFFFFFFFF		; free?
	jr z, .Ltco_slot1
	lds hl, 0			; occupied → return 0
	jrl .Ltco_exit
	; --- Slot 1: base 0x20165A ---
.Ltco_slot1:
	ld wa, (xsp + 4)
	extz xwa
	ld xbc, 0x0000004C
	call HDAE5000_Multiply
	ld xiz, xhl
	ld wa, (xsp + 6)
	extz xwa
	ld xbc, 0x000004C0
	call HDAE5000_Multiply
	add xhl, 0x00000780
	add xhl, xiz
	lda_24 xwa, 0x20165a                  ; 0x20165A
	add xwa, xhl
	ld xwa, (xwa)
	cp xwa, 0xFFFFFFFF
	jr z, .Ltco_slot2
	lds hl, 0
	jrl .Ltco_exit
	; --- Slot 2: base 0x20165E ---
.Ltco_slot2:
	ld wa, (xsp + 4)
	extz xwa
