	ld wa, (xsp + 6)
	extz xwa
	ld xbc, 0x000004C0
	call HDAE5000_Multiply
	add xhl, 0x00000780
	add xhl, xiz
	lda_24 xwa, 0x201662                  ; 0x201662
	add xwa, xhl
	ld xwa, (xwa)
	cp xwa, 0xFFFFFFFF
	jr z, .Ltco_slot4
