.Lws36b_bit8:
	bit 8, iz
	jr z, .Lws36b_calc
	ld wa, (xsp + 6)
	ld bc, (xsp + 4)
	calr HDAE5000_Cell_Render_Type8
.Lws36b_calc:
	; Calculate table offset
	ld wa, (xsp + 6)
	ld bc, (xsp + 4)
	calr HDAE5000_Table_Calc_Offset
	cp hl, 0xFFFF
	jr nz, .Lws36b_post
	; Push args and call 0x29AEC7
	pushw 0x001A
	pushw 0x0020
	ld wa, (xsp + 8)
	extz xwa
	ld xbc, 0x0000004C
	call 0x29B72D
	ld xiz, xhl
	ld wa, (xsp + 10)
	extz xwa
	ld xbc, 0x000004C0
	call 0x29B72D
	add xhl, 0x780
	add xhl, xiz
	ld xwa, 0x00201632
	add xwa, xhl
	push xwa
	call 0x29AEC7
	inc 0, xsp
	; Call workspace handler
	ld wa, (xsp + 6)
	ld bc, (xsp + 4)
	calr HDAE5000_Workspace_Handler
.Lws36b_post:
	call 0x297A78
	; Conditional call NZ to 0x2974B5
	cpw (xsp + 12), 0x0001
	call_24 nz, 2716853	; call nz, 0x2974B5
	; Check workspace flag at (xsp+14)
	cpw (xsp + 14), 0x0001
	jr nz, .Lws36b_skip2
	; Workspace dispatch at 0x053C
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e0a)
	ld_sril xhl, (xwa + 0x053c)
	call (xhl)
.Lws36b_skip2:
	; Workspace dispatch at 0xEC
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e88)
	ld_sril xhl, (xwa + 0x00ec)
	call (xhl)
	; Workspace dispatch at 0xF0
	ld32_24 xwa, 0x23a1a2
	ld_sril xwa, (xwa + 0x0e88)
	ld_sril xhl, (xwa + 0x00f0)
	call (xhl)
.Lws36b_exit:
	pop xiz
	inc 4, xsp
	retd 4

; --- UI Cell Renderers (9 x 222 bytes each) ---
; Delete table entry: check existence, call handler, clear entry (-1), clear flag (0)
HDAE5000_Cell_Render_Type0:	; 0x2934C8 (222 bytes)
	dec 4, xsp
	push xiz
	ld (xsp + 4), bc	; save file number
	ld (xsp + 6), wa	; save partition
	; --- Check if entry exists ---
	ld wa, (xsp + 4)
	extz xwa
	ld xbc, 0x0000004C	; multiplier = 76
	call 0x29B72D
	ld xiz, xhl
	ld wa, (xsp + 6)
	extz xwa
	ld xbc, 0x000004C0	; multiplier = 1216
	call 0x29B72D
	add xhl, 0x780		; += 1920
	add xhl, xiz
	lda_24 xwa, 0x201656                  ; 0x201656 (table base)
	add xwa, xhl
	ld xwa, (xwa)
	cp xwa, 0xFFFFFFFF
	jrl z, .Lcr0_exit
	; --- Get entry value and call handler ---
	ld wa, (xsp + 4)
	extz xwa
	ld xbc, 0x0000004C
	call 0x29B72D
	ld xiz, xhl
	ld wa, (xsp + 6)
	extz xwa
	ld xbc, 0x000004C0
	call 0x29B72D
	add xhl, 0x780
	add xhl, xiz
	lda_24 xwa, 0x201656                  ; 0x201656
	add xwa, xhl
	ld xwa, (xwa)
	call 0x298590
	; --- Clear entry (store -1) ---
	ld wa, (xsp + 4)
	extz xwa
	ld xbc, 0x0000004C
	call 0x29B72D
	ld xiz, xhl
	ld wa, (xsp + 6)
	extz xwa
	ld xbc, 0x000004C0
	call 0x29B72D
	add xhl, 0x780
	add xhl, xiz
	lda_24 xwa, 0x201656                  ; 0x201656
	ld xbc, xwa
	add xbc, xhl
	ld xwa, 0xFFFFFFFF
	ld (xbc), xwa
	; --- Clear flag (store 0) ---
	ld wa, (xsp + 4)
	extz xwa
	ld xbc, 0x0000004C
	call 0x29B72D
	ld xiz, xhl
	ld wa, (xsp + 6)
	extz xwa
	ld xbc, 0x000004C0
	call 0x29B72D
	add xhl, 0x780
	add xhl, xiz
	lda_24 xwa, 0x20164c                  ; 0x20164C (flag base)
	add xwa, xhl
	ld (xwa), 0x00
.Lcr0_exit:
	pop xiz
	inc 4, xsp
	ret

