	ld (xix), a				; store to buffer[0]
	ld8_24 a, 0x2390e4                    ; ld A, (0x2390E4) — masked head
	nop
	ld (xix + 1), a			; store to buffer[1]
	nop
	add xix, 44				; advance XIX by 0x2C (44 bytes)
