	nop
	ld (xix), xwa
	inc 4, xix
	ld32_24 xwa, 0x239124                 ; ld XWA, (0x239124) — region 2
	nop
	ld (xix), xwa
	inc 4, xix
	ld32_24 xwa, 0x23912c                 ; ld XWA, (0x23912C) — region 3
	nop
	ld (xix), xwa
	inc 4, xix
