	inc 2, xiy                              ; inc 2,XIY
	jp 0x2971bf                             ; jp 0x2971bf
	lda_24 xiy, 0x230f1c
	cp	xiy, 0x00238f1c
	.byte 0xf2, 0xf5, 0x71, 0x29, 0xd6     ; jp Z,0x2971f5
